return ['x-generator'=>'GlotPress/4.0.3','translation-revision-date'=>'2026-05-21 05:09:14+0000','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','project-id-version'=>'Plugins - WP Mail SMTP by WPForms &#8211; The Most Popular SMTP and Email Log Plugin - Stable (latest release)','language'=>'pl','messages'=>['API Keys'=>'Klucze API','Follow this link to get the API key from Resend: %s.'=>'Aby uzyskać klucz API z Resend, kliknij poniższy odnośnik: %s.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Resend documentation</a>.'=>'Aby rozpocząć, przeczytaj naszą <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentację Resend</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Resend</a> is a modern email delivery platform that enables developers to send transactional and marketing emails quickly and reliably. If you\'re just getting started, you can send up to 3000 emails per month without a credit card.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Resend</a> to nowoczesna platforma do wysyłki wiadomości e-mail, która umożliwia programistom szybkie i niezawodne wysyłanie wiadomości transakcyjnych i marketingowych. Jeśli dopiero zaczynasz, możesz wysyłać do 3000 wiadomości miesięcznie bez karty kredytowej.','Read how to set up Resend'=>'Przeczytaj, jak skonfigurować Resend','%1$sFollow this link%2$s to get an API Key for Resend.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać klucz API dla Resend.','Send WordPress emails reliably via SMTP or API using SendLayer, Brevo, SMTP.com, Gmail, Outlook, or another email service of your choice.'=>'Niezawodnie wysyłaj wiadomości e-mail w WordPressie przez SMTP lub API, korzystając z SendLayer, Brevo, SMTP.com, Gmail, Outlook lub innej wybranej przez siebie usługi poczty e-mail.','Follow this link to get an API Key from Mandrill: %s.'=>'Aby uzyskać klucz API od Mandrill, kliknij poniższy odnośnik: %s.','Mandrill'=>'Mandrill','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Mandrill documentation</a>.'=>'Aby rozpocząć, przeczytaj naszą <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentację Mandrill</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Mandrill</a> is a transactional email API for MailChimp users. It is a reliable, scalable, and secure delivery API for transactional emails. Mandrill requires a paid monthly subscription to send emails.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Mandrill</a> to interfejs API do obsługi wiadomości e-mail w transakcjach transakcyjnych dla użytkowników MailChimp. Jest to niezawodny, skalowalny i bezpieczny interfejs API do dostarczania wiadomości e-mail w transakcjach transakcyjnych. Do wysyłania wiadomości e-mail Mandrill wymaga płatnej miesięcznej subskrypcji.','The email failed to be sent. Reason: %s'=>'Nie udało się wysłać wiadomości e-mail. Powód: %s','<strong>%s OFF</strong> for WP Mail SMTP users, applied at checkout.'=>'<strong>%s ZNIŻKI</strong> dla użytkowników WP Mail SMTP, naliczana przy kasie.','Discount'=>'Rabat','Professional Setup and World-Class Support'=>'Profesjonalna konfiguracja i wsparcie na światowym poziomie','White Glove Setup - Sit back while we handle everything'=>'Konfiguracja w białych rękawiczkach – usiądź wygodnie, a my zajmiemy się wszystkim','Smart Routing, Multisite Support, and Manage Notifications'=>'Inteligentne trasowanie, obsługa wielu lokalizacji i zarządzanie powiadomieniami','Effortless Management - Control your email experience'=>'Łatwe zarządzanie - kontroluj swoją pocztę e-mail','Gmail one-click setup, Microsoft 365 / Outlook, Amazon SES, and Zoho Mail'=>'Konfiguracja Gmaila jednym kliknięciem, Microsoft 365 / Outlook, Amazon SES i Zoho Mail','Professional Email Services - Access enterprise-grade email providers'=>'Profesjonalne usługi poczty e-mail - Uzyskaj dostęp do dostawców poczty e-mail klasy korporacyjnej','Email Logging, Alerts, and Backup Connection'=>'Rejestrowanie poczty e-mail, alerty i połączenie kopii zapasowej','Peace of Mind - Never wonder about your email status'=>'Spokój ducha - Nigdy nie zastanawiaj się nad statusem swojej poczty e-mail','Key Features You’ll Unlock:'=>'Główne funkcje, które odblokujesz:','Upgrade and join over <strong>4,000,000</strong> websites!'=>'Ulepsz i dołącz do ponad <strong>4 000 000</strong> witryn internetowych!','Level Up Your Email Game - Get Pro Features Now'=>'Ulepsz swoją pocztę e-mail - Uzyskaj funkcje Pro już teraz','Email Logs'=>'Dzienniki e-mail','As a valued WP Mail SMTP Lite user, you can enjoy an exclusive <strong>%s discount</strong>, automatically applied at checkout to unlock even more features!'=>'Jako ceniony użytkownik WP Mail SMTP Lite możesz skorzystać z ekskluzywnej zniżki <strong>%s</strong>, która zostanie automatycznie naliczona podczas realizacji transakcji, aby odblokować jeszcze więcej funkcji!','You\'re using <strong>WP Mail SMTP Lite</strong> - no license needed. Enjoy!'=>'Używasz <strong>WP Mail SMTP Lite</strong> - licencja nie jest wymagana. Miłej zabawy!','You’re using WP Mail SMTP Lite. To unlock more features, consider <a href="%1$s" target="_blank" rel="noopener noreferrer">upgrading to Pro</a> for <strong>%2$s OFF</strong>.'=>'Używasz WP Mail SMTP Lite. Aby odblokować więcej funkcji, rozważ <a href="%1$s" target="_blank" rel="noopener noreferrer">ulepszenie do Pro</a>, aby uzyskać <strong>%2$s ZNIŻKI</strong>.','Read how to set up Mandrill'=>'Przeczytaj, jak skonfigurować Mandrill','Follow this link to get an API Key from Mandrill.'=>'Kliknij ten odnośnik, aby uzyskać klucz API od Mandrill.','pricing page'=>'strona cenowa','Activate if you have a Professional or higher plan with MailerSend. This allows you to use custom headers. For more information about MailerSend plans, check their %s.'=>'Włącz, jeśli masz plan Professional lub wyższy z MailerSend. Pozwala to na używanie niestandardowych nagłówków. Aby uzyskać więcej informacji o planach MailerSend, sprawdź ich %s.','Professional Plan'=>'Plan Profesjonalny','Follow this link to get an API Key from MailerSend: %s.'=>'Kliknij poniższy odnośnik, aby uzyskać klucz API od MailerSend: %s.','MailerSend'=>'MailerSend','<a href="%1$s" target="_blank" rel="noopener noreferrer">MailerSend</a> is a reliable transactional email provider with powerful features. They offer 12,000 emails per month for free and have affordable plans for higher volumes. Their modern API and excellent deliverability make them a great choice for WordPress sites.<br><br>To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">MailerSend documentation</a>.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">MailerSend</a> to niezawodny dostawca poczty transakcyjnej z potężnymi funkcjami. Oferuje 12 000 wiadomości e-mail miesięcznie za darmo i ma przystępne plany na większe wolumeny. Ich nowoczesne API i doskonała dostarczalność sprawiają, że są doskonałym wyborem dla witryn WordPress.<br><br>Aby rozpocząć, przeczytaj naszą <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentację MailerSend</a>.','When selected, emails blocked by the "Do Not Send" option will be logged in the Email Log.'=>'Po wybraniu tej opcji wiadomości e-mail zablokowane przez opcję „Nie wysyłaj” będą rejestrowane w dzienniku wiadomości e-mail.','Log Blocked Emails'=>'Rejestruj zablokowane wiadomości e-mail','Phone Number ID'=>'Identyfikator numeru telefonu','WhatsApp Business Account ID'=>'Identyfikator konta firmowego WhatsApp','Access Token'=>'Token dostępu','WhatsApp Alerts'=>'Alerty WhatsApp','Enter your WhatsApp Cloud API credentials to receive alerts when email sending fails. You\'ll need to create a Meta developer account and set up WhatsApp Business Platform.'=>'Wprowadź swoje dane uwierzytelniające WhatsApp Cloud API, aby otrzymywać alerty, gdy wysyłanie wiadomości e-mail się nie powiedzie. Musisz utworzyć konto programisty Meta i skonfigurować platformę WhatsApp Business.','WhatsApp'=>'WhatsApp','Read how to set up MailerSend'=>'Przeczytaj, jak skonfigurować MailerSend','Enable if you have a Pro plan or higher to use advanced features like custom headers.'=>'Włącz, jeśli masz plan Pro lub wyższy, aby korzystać z zaawansowanych funkcji, takich jak niestandardowe nagłówki.','Pro Plan Features'=>'Funkcje planu Pro','Notice was successfully dismissed.'=>'Powiadomienie zostało odrzucone.','Push Notifications'=>'Powiadomienia push','To receive push notifications on this device, you\'ll need to allow our plugin to send notifications via this browser. Read our documentation on setting up Push Notification alerts.'=>'Aby otrzymywać powiadomienia push na tym urządzeniu, musisz zezwolić naszej wtyczce na wysyłanie powiadomień za pośrednictwem tej przeglądarki. Zapoznaj się z naszą dokumentacją dotyczącą konfigurowania alertów w postaci powiadomień push.','Connection Name'=>'Nazwa połączenia','Push Notification Alerts'=>'Alerty powiadomień push','<a href="%1$s" target="_blank" rel="noopener noreferrer">Elastic Email</a> is a cloud-based email marketing platform offering tools for email campaigns, automation, transactional emails, and analytics, designed for businesses of all sizes.<br><br>If you\'re just starting out, you can use Elastic Email\'s free plan to send emails to your account address from one of your verified email addresses. You don\'t need to use a credit card to try it out. When you\'re ready, you can upgrade to a higher plan.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Elastic Email</a> to działająca w chmurze platforma marketingu e-mail, która udostępnia narzędzia do kampanii e-mail, automatyzacji, e-maili transakcyjnych i analiz przeznaczone dla firm każdej wielkości.<br><br>Jeśli dopiero zaczynasz, możesz skorzystać z bezpłatnego planu Elastic Email, aby wysyłać e-maile na adres swojego konta z jednego ze swoich zweryfikowanych adresów e-mail. Do wypróbowania tej platformy nie jest potrzebna karta kredytowa. W wybranym przez siebie momencie możesz przejść na wyższy plan.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Elastic Email documentation</a>.'=>'Na początek zapoznaj się z naszą <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentacją usługi Elastic Email</a>.','Elastic Email'=>'Elastic Email','Follow this link to get an API Key from Elastic Email: %s.'=>'Kliknij ten odnośnik, aby uzyskać klucz API z usługi Elastic Email: %s.','<strong>%1$s</strong><br>Heads up! Microsoft is <a href="%2$s" target="_blank" rel="noopener noreferrer">discontinuing support for basic SMTP connections</a>. To continue using Outlook or Hotmail, switch to our Outlook mailer for uninterrupted email sending.'=>'<strong>%1$s</strong><br>Uwaga! Microsoft <a href="%2$s" target="_blank" rel="noopener noreferrer">zaprzestaje obsługi podstawowych połączeń SMTP</a>. Aby nadal korzystać z Outlooka lub Hotmaila, przejdź się na usługę pocztową Outlook w celu nieprzerwanego wysyłania e-maili.','%1$s <a href="%2$s" target="_blank" rel="noopener noreferrer">Upgrade to Pro now for easy, one-click Outlook setup</a>.'=>'%1$s <a href="%2$s" target="_blank" rel="noopener noreferrer">Już teraz kup Pro, aby móc łatwo skonfigurować usługę Outlook jednym kliknięciem</a>.','Read how to set up Elastic Email'=>'Poznaj sposób konfiguracji usługi Elastic Email','%1$sFollow this link%2$s to get an API Key for Elastic Email.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać klucz API usługi Elastic Email.','Provides a quick and easy way to connect to Outlook that doesn\'t require creating your own app.'=>'Udostępnia szybki i łatwy sposób na połączenie się z usługą Outlook, który nie wymaga tworzenia własnej aplikacji.','You have successfully connected your site with your Outlook account. Now you can start sending emails through Outlook.'=>'Twoja witryna została połączona z kontem Outlook. Teraz możesz rozpocząć wysyłanie e-maili za pośrednictwem Outlooka.','Sign in with Outlook'=>'Zaloguj się za pomocą konta Outlook','One-Click Setup for Microsoft Outlook requires an active license. Verify your license to proceed with this One-Click Setup, please.'=>'Konfiguracja usługi Microsoft Outlook jednym kliknięciem wymaga włączonej licencji. Zweryfikuj licencję, aby kontynuować procedurę konfiguracji jednym kliknięciem.','Paste in the Discord webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up Discord alerts.'=>'Wklej adres URL webhooka Discorda, którego chcesz używać do otrzymywania alertów w przypadku, gdy wysłanie e-maila się nie powiedzie. Zapoznaj się z naszą dokumentacją dotyczącą konfigurowania alertów przez Discord.','Discord Alerts'=>'Alerty przez Discord','Remove API Key'=>'Usuń klucz API','Remove Client Secret'=>'Usuń klucz prywatny klienta','<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailjet</a> is a cloud-based email service platform that enables businesses to send marketing and transactional emails, offering features like email automation, real-time analytics, and responsive design templates. If you\'re just starting out, you can send up to 200 emails per day without a credit card.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailjet</a> to działająca w chmurze platforma usług e-mail, która umożliwia firmom wysyłanie e-maili marketingowych i transakcyjnych oraz oferuje takie funkcje jak automatyzacja e-maili, analizy w czasie rzeczywistym i responsywne szablony projektowe. Jeśli dopiero zaczynasz, możesz wysyłać do 200 e-maili dziennie bez karty kredytowej.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Mailjet documentation</a>.'=>'Na początek zapoznaj się z naszą <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentacją usługi Mailjet</a>.','Mailjet'=>'Mailjet','Follow this link to get the API key from Mailjet: %s.'=>'Kliknij ten odnośnik, aby uzyskać klucz API z usługi Mailjet: %s.','API Key Management'=>'Zarządzanie kluczami API','Remove Secret Key'=>'Usuń klucz prywatny','Follow this link to get the Secret key from Mailjet: %s.'=>'Kliknij ten odnośnik, aby uzyskać klucz prywatny z usługi Mailjet: %s.','Remove Server API Token'=>'Usuń token API serwera','Secret Key'=>'Klucz prywatny','Follow this link to get an API key and Secret key from Mailjet: %1$sAPI Key Management%2$s.'=>'Kliknij ten odnośnik, aby uzyskać klucz API i klucz prywatny z usługi Mailjet: %1$szarządzanie kluczami API%2$s.','Read how to set up Mailjet'=>'Poznaj sposób konfiguracji usługi Mailjet','Follow this link to get the API key from Mailjet: %1$sAPI Key Management%2$s.'=>'Kliknij ten odnośnik, aby uzyskać klucz API z usługi Mailjet: %1$szarządzanie kluczami API%2$s.','Follow this link to get the Secret key from Mailjet: %1$sAPI Key Management%2$s.'=>'Kliknij ten odnośnik, aby uzyskać klucz prywatny z usługi Mailjet: %1$szarządzanie kluczami API%2$s.','Charitable'=>'Charitable','Discord'=>'Discord','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">SMTP2GO documentation</a>.'=>'Na początek zapoznaj się z naszą <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentacją usługi SMTP2GO</a>.','SMTP2GO'=>'SMTP2GO','Generate an API key on the Sending &rarr; API Keys page in your %s.'=>'Wygeneruj klucz API na stronie Wysyłanie &rarr; Klucze API w obszarze %s.','control panel'=>'panel sterowania','<a href="%1$s" target="_blank" rel="noopener noreferrer">SMTP2GO</a> provides a robust and reliable email delivery service with global infrastructure, real-time analytics, and advanced security features. If you\'re just starting out, you can use SMTP2GO\'s free plan to send up to 1000 emails per month.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">SMTP2GO</a> to solidna i niezawodna usługa dostarczania e-maili udostępniająca globalną infrastrukturę, analizy w czasie rzeczywistym i zaawansowane funkcje zabezpieczeń. Początkujący użytkownicy mogą skorzystać z bezpłatnego planu SMTP2GO, który umożliwia wysyłanie do 1000 e-maili miesięcznie.','Generate an API key on the Sending → API Keys page in your %1$scontrol panel%2$s.'=>'Wygeneruj klucz API na stronie Wysyłanie → Klucze API w %1$spanelu sterowania%2$s.','Read how to set up SMTP2GO'=>'Poznaj sposób konfiguracji usługi SMTP2GO','Microsoft Teams'=>'Microsoft Teams','Paste in the Microsoft Teams webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up Microsoft Teams alerts.'=>'Wklej adres URL webhooka Microsoft Teams, którego chcesz używać do otrzymywania alertów w przypadku, gdy wysłanie e-maila się nie powiedzie. Zapoznaj się z naszą dokumentacją dotyczącą konfigurowania alertów Microsoft Teams.','Microsoft Teams Alerts'=>'Alerty Microsoft Teams','Remove'=>'Usuń','Remove Password'=>'Usuń hasło','[Emails Queue] Skipped enqueueing email. %1$s.'=>'[kolejka e-maili] Pominięto dodawanie e-maila do kolejki. %1$s.','Insert/update SQL query error: %1$s'=>'Błąd zapytania SQL insert/update: %1$s','Data JSON encoding error: %1$s'=>'Błąd kodowania danych JSON: %1$s','Data JSON decoding error: %1$s'=>'Błąd dekodowania danych JSON: %1$s','Invalid record format'=>'Błędny format rekordu','Record not found in DB'=>'Nie znaleziono rekordu w bazie danych','That\'s fantastic! Would you consider giving it a 5-star rating on WordPress.org? It will help other users with email issues and it will mean the world to us!'=>'Fantastycznie! Rozważ danie nam 5-gwiazdkowej oceny na WordPress.org. To pomoże innym użytkownikom w problemach z e-mailem i znaczy dla nas naprawdę wiele!','Yes, I\'ll rate it with 5-stars'=>'Tak, dam 5 gwiazdek','[Emails Queue] Skipped processing enqueued email. %1$s. Email ID: %2$d'=>'[Pominięto przetwarzanie wiadomości e-mail w kolejce. %1$s. Identyfikator wiadomości e-mail: %2$d','[Emails Queue] Failed to update queue record after sending email from the queue. %1$s. Email ID: %2$d'=>'[Nie udało się zaktualizować kolejki po wysłaniu wiadomości e-mail. %1$s. Identyfikator wiadomości e-mail: %2$d','[Emails Queue] Skipped email sending from the queue. Wrong email status. Email ID: %1$d, email status: %2$s.'=>'[Pominięto wysyłanie wiadomości e-mail z kolejki. Nieprawidłowy status wiadomości. Identyfikator wiadomości e-mail: %1$d, status wiadomości e-mail: %2$s.','[Emails Queue] Skipped email sending from the queue. %1$s. Email ID:  %2$s'=>'[Pominięto wysyłanie wiadomości e-mail z kolejki. %1$s. Identyfikator wiadomości e-mail: %2$s','[Emails Queue] Skipped email sending from the queue. Queue::send_email method was called directly. Email ID: %1$d.'=>'[Pominięto wysyłanie wiadomości e-mail z kolejki. Metoda queue::send_email została wywołana bezpośrednio. Identyfikator wiadomości e-mail: %1$d.','No'=>'Nie','Optimize Email Sending'=>'Optymalizuj wysyłanie e-maili','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it seems they are missing. Please try to <a href="%1$s">create the missing DB tables by clicking on this link</a>. If this issue persists, please <a href="%2$s" target="_blank" rel="noopener noreferrer">contact our support</a> and provide the error message below:'=>'WP Mail SMTP używa własnych tabel bazy danych dla części funkcji. Aby to działało poprawnie, własne tabele muszą zostać utworzone, ale wygląda na to, że ich nie ma. Proszę spróbuj <a href="%1$s">utworzyć brakujące tabele bazy danych klikając ten odnośnik</a>. Jeżeli problem pozostanie, <a href="%2$s" target="_blank" rel="noopener noreferrer">skontaktuj się z pomocą techniczną</a> i podaj im poniższy komunikat błędu:','Provide Feedback'=>'Przekaż opinię','Limit the number of emails this site will send in each time interval (per minute, hour, day, week and month). Emails that will cross those set limits will be queued and sent as soon as your limits allow. <a href="%1$s" target="_blank" rel="noopener noreferrer">Learn More</a>'=>'Ogranicz liczbę wiadomości e-maili, które witryna wysyła w każdym przedziale czasu (na minutę, godzinę, dzień, tydzień i miesiąc) wiadomości które przekroczą limit zostaną dodane do kolejki i wysłane natychmiast, jak tylko limity pozwolą. <a href="%1$s" target="_blank" rel="noopener noreferrer">Dowiedz się więcej</a>','Email Rate Limiting'=>'Ograniczenie częstotliwości wysyłanych wiadomości e-mail','Send emails asynchronously, which will make pages with email requests load faster, but may delay email delivery by a minute or two. <a href="%1$s" target="_blank" rel="noopener noreferrer">Learn More</a>'=>'Wysyłaj e-maile asynchronicznie, co powoduje, że strony wysyłające e-maile ładują się szybciej, ale e-maile mogą zostać dostarczone minutę lub dwie później. <a href="%1$s" target="_blank" rel="noopener noreferrer">Dowiedz się więcej</a>','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it seems they are missing. Please try to <a href="%1$s">create the missing DB tables by clicking on this link</a>. If this issue persists, please <a href="%2$s" target="_blank" rel="noopener noreferrer">contact our support</a>.'=>'WP Mail SMTP używa niestandardowych tabel bazy danych dla niektórych swoich funkcji. Aby działać prawidłowo, należy utworzyć niestandardowe tabele, a wygląda na to, że ich brakuje. Spróbuj <a href="%1$s">utworzyć brakujące tabele bazy danych, klikając ten odnośnik</a>. Jeśli ten problem będzie się powtarzał, <a href="%2$s" target="_blank" rel="noopener noreferrer">skontaktuj się z naszym działem pomocy</a>.','Email Rate Limiting <br> is a Pro Feature'=>'Ograniczenie częstotliwości wysyłanych e-maili <br> jest funkcją płatną.','We\'re sorry, Email Rate Limiting is not available on your plan. Please upgrade to the Pro plan to unlock all these awesome features.'=>'Przepraszamy, ograniczenie częstotliwości wysyłanych e-maili jest niedostępne w twoim planie. Ulepsz do planu profesjonalnego, aby odblokować te wszystkie wspaniałe funkcje.','Install the WPForms plugin and create beautiful contact forms with just a few clicks.'=>'Zainstaluj wtyczkę WPForms aby kilkoma kliknięciami tworzyć piękne formularze kontaktowe.','Our Gmail mailer works with any Gmail or Google Workspace account via the Google API. You can send WordPress emails from your main email address or a Gmail alias, and it\'s more secure than connecting to Gmail using SMTP credentials. We now have a One-Click Setup, which simply asks you to authorize your Google account to use our app and takes care of everything for you. Alternatively, you can connect manually, which involves several steps that are more technical than other mailer options, so we created a detailed guide to walk you through the process.<br><br>To get started, read our <a href="%s" target="_blank" rel="noopener noreferrer">Gmail documentation</a>.'=>'Nasza usługa pocztowa Gmail współpracuje z dowolnym kontem Gmail lub Google Workspace za pośrednictwem interfejsu Google API. Możesz wysyłać e-maile w WordPressie ze swojego głównego adresu e-mail lub aliasu w usłudze Gmail i jest to bezpieczniejsze niż łączenie się z usługą Gmail przy użyciu poświadczeń SMTP. Teraz dostępna jest funkcja konfiguracji jednym kliknięciem, która po prostu cię o autoryzację korzystania przez konto Google z naszej aplikacji i robi wszystko za ciebie. Możesz też ustanowić połączenie ręcznie, co wymaga wykonania kilku czynności o nieco bardziej technicznym charakterze niż w przypadku innych opcji usług pocztowych, i dlatego przygotowaliśmy szczegółowy przewodnik, który cię przez nie przeprowadzi.<br><br>Aby rozpocząć, zapoznaj się z <a href="%s" target="_blank" rel="noopener noreferrer">dokumentacją usługi Gmail</a>.','One-Click Setup'=>'Konfiguracja jednym kliknięciem','Provides a quick and easy way to connect to Google that doesn\'t require creating your own app.'=>'Zapewnia szybki i łatwy sposób na połączenie z Google, który nie wymaga tworzenia własnej aplikacji.','Enabled'=>'Włączono','Disabled'=>'Wyłączono','Sign in with Google'=>'Zaloguj się przez Google','There was an error while processing the authentication request.'=>'Podczas przetwarzania żądania uwierzytelnienia wystąpił błąd.','Now you can continue mailer configuration.'=>'Teraz możesz kontynuować konfigurację usługi pocztowej.','Gmail mailer requires a valid Easy WP SMTP Pro license. Please activate your license key.'=>'Usługa pocztowa Gmail wymaga ważnej licencji wtyczki Easy WP SMTP Pro. Włącz swój klucz licencyjny.','One-Click Setup for Google Mailer requires an active license. Emails are currently not being sent.'=>'Konfiguracja usługi pocztowej Google jednym kliknięciem wymaga włączonej licencji. E-maile nie są obecnie wysyłane.','One-Click Setup for Google Mailer requires an active license. Verify your license to proceed with this one-click setup.'=>'Konfiguracja usługi pocztowej Google jednym kliknięciem wymaga włączonej licencji. Zweryfikuj licencję, aby kontynuować procedurę konfiguracji jednym kliknięciem.','One-Click Setup for Google Mailer requires an active license. Verify your license to proceed with this one-click setup, please.'=>'Konfiguracja usługi pocztowej Google jednym kliknięciem wymaga włączonej licencji. Zweryfikuj licencję, aby kontynuować procedurę konfiguracji jednym kliknięciem.','One-Click Setup for Google Mailer requires an active license. Verify your license to proceed with this One-Click Setup, please.'=>'Konfiguracja usługi pocztowej Google jednym kliknięciem wymaga włączonej licencji. Zweryfikuj licencję, aby kontynuować procedurę konfiguracji jednym kliknięciem.','You have successfully connected your site with your Gmail account. This site will now send emails via your Gmail account.'=>'Udało się połączyć witrynę z kontem Gmail. Witryna będzie teraz wysyłać e-maile za pośrednictwem twojego konta Gmail.','You have successfully connected your site with your Gmail account. Now you can start sending emails through Gmail.'=>'Udało się połączyć witrynę z kontem Gmail. Możesz rozpocząć wysyłanie e-maili za pośrednictwem usługi Gmail.','The email address that emails are sent from. You can use only connected email address or '=>'Adres e-mail, z którego wysyłane są e-maile. Możesz użyć tylko połączonego adresu e-mail lub ','The email address that emails are sent from. You can use only connected email address or his alias.'=>'Adres e-mail, z którego wysyłane są e-maile. Możesz użyć tylko połączonego adresu e-mail lub jego aliasu.','The email address that emails are sent from. The email address that emails are sent from. You can use only the connected email address or its alias.'=>'Adres e-mail, z którego wysyłane są e-maile. Możesz użyć tylko połączonego adresu e-mail lub jego aliasu.','The email address that emails are sent from. You can use only the connected email address or its alias.'=>'Adres e-mail, z którego wysyłane są e-maile. Możesz użyć tylko połączonego adresu e-mail lub jego aliasu.','One-Click Setup for Google Mailer <br> is a Pro Feature'=>'Konfiguracja usługi pocztowej Google <br> jednym kliknięciem to funkcja Pro','We\'re sorry, One-Click Setup for Google Mailer is not available on your plan. Please upgrade to the Pro plan to unlock all these awesome features.'=>'Niestety, konfiguracja usługi pocztowej Google jednym kliknięciem nie jest dostępna w twoim planie. Kup plan Pro, aby uzyskać dostęp do tej i innych fantastycznych funkcji.','Send emails from different additional connections based on your configured conditions. Emails that do not match any of the conditions below will be sent via your Primary Connection.'=>'Wysyłaj e-maile przy użyciu różnych dodatkowych połączeń na podstawie skonfigurowanych przez siebie warunków. E-maile niespełniające żadnego z poniższych warunków będą wysyłane za pośrednictwem połączenia podstawowego.','Email reports make it easy to track deliverability and engagement at-a-glance. Your open and click-through rates are grouped by subject line, making it easy to review the performance of campaigns or notifications. The report also displays Sent and Failed emails each week so you spot any issues quickly. When you upgrade, we\'ll also add an email report chart right in your WordPress dashboard.'=>'Raporty o e-mailach ułatwiają sprawne monitorowanie skuteczności dostarczania i stopnia zaangażowania. Wskaźniki otwarć i kliknięć są pogrupowane według tematów, co ułatwia sprawdzanie skuteczności kampanii lub powiadomień. Raport pokazuje również liczbę wysłanych i nieudanych e-maili w każdym tygodniu, dzięki czemu umożliwia szybkie wykrywanie ewentualnych problemów. W przypadku ulepszenia planu zyskasz też dostęp do wykresu raportu o e-mailach, który znajdziesz bezpośrednio w kokpicie WordPressa.','Miscellaneous'=>'Różne','Remove ALL WP Mail SMTP data upon plugin deletion.'=>'Usuń WSZYSTKIE dane wtyczki WP Mail SMTP z chwilą jej usunięcia.','All settings will be unrecoverable.'=>'Nie będzie można odzyskać żadnych ustawień.','Easily export your logs to CSV or Excel. Filter the logs before you export and only download the data you need. This feature lets you easily create your own deliverability reports. You can also use the data in 3rd party dashboards to track deliverability along with your other website statistics.'=>'Z łatwością eksportuj dzienniki w formacie CSV lub Excel. Przed eksportem możesz przefiltrować dziennik, aby pobrać tylko potrzebne dane. Ta funkcja umożliwia łatwe tworzenie własnych raportów dotyczących dostarczania e-maili. Możesz również używać danych dostępnych w zewnętrznych kokpitach, aby śledzić skuteczność dostarczania razem z innymi statystykami swojej witryny.','Email logging makes it easy to save details about all of the emails sent from your WordPress site. You can search and filter the email log to find specific messages and check the color-coded delivery status. Email logging also allows you to resend emails, save attachments, and export your logs in different formats.'=>'Rejestrowanie e-maili ułatwia dostęp do szczegółowych informacji na temat wszystkich e-maili wysyłanych z twojej witryny w WordPressie. Przeszukując i filtrując dziennik e-maili, możesz znajdować określone wiadomości i sprawdzać statusy dostarczenia oznaczone kolorem. Ponadto funkcja rejestrowania e-maili umożliwia ponowne wysyłanie wiadomości, zapisywanie załączników i eksportowanie dzienników w różnych formatach.','Get notified about emails that were successfully sent, but have hard bounced on delivery attempt. A hard bounce is an email that has failed to deliver for permanent reasons, such as the recipient\'s email address being invalid.'=>'Zyskaj dostęp do powiadomień o e-mailach, które po pomyślnym wysłaniu zostały trwale odrzucone przy próbie dostarczenia. Trwałe odrzucenie oznacza, że nie udało się dostarczyć e-maila z przyczyn o charakterze permanentnym, takich jak nieprawidłowy adres e-mail adresata.','Email controls allow you to manage the automatic notifications you receive from your WordPress website. With the flick of a switch, you can reduce inbox clutter and focus on the alerts that matter the most. It\'s easy to disable emails about comments, email or password changes, WordPress updates, user registrations, and personal data requests.'=>'Kontrola nad e-mailami umożliwia zarządzanie automatycznymi powiadomieniami, które otrzymujesz ze swojej witryny internetowej w WordPressie. Przez zmianę odpowiedniego przełącznika możesz ograniczyć bałagan w skrzynce odbiorczej i skupić się na najważniejszych powiadomieniach. Z łatwością wyłączysz e-maile na temat komentarzy, zmian adresów e-mail lub haseł, aktualizacji WordPressa, rejestracji użytkowników i próśb dotyczących danych osobowych.','Improve your SEO rankings with the All in One SEO plugin.'=>'Popraw pozycję swojej witryny w wynikach wyszukiwania dzięki wtyczce All in One SEO.','Made with ♥ by the WP Mail SMTP team'=>'Stworzona z ♥ przez zespół WP Mail SMTP','Support'=>'Pomoc techniczna','Free Plugins'=>'Bezpłatne wtyczki','Create additional connections to set a backup for your Primary Connection or to configure Smart Routing.'=>'Utwórz dodatkowe połączenia, aby przygotować zapas dla połączenia podstawowego lub skonfigurować inteligentne przekierowywanie.','Configure at least one of these integrations to receive notifications when email fails to send from your site. Alert notifications will contain the following important data: email subject, email Send To address, the error message, and helpful links to help you fix the issue.'=>'Skonfiguruj co najmniej jedną z tych integracji, aby otrzymać powiadomienie w przypadku, gdy wysyłanie e-maila z twojej witryny zakończy się niepowodzeniem. Powiadomienia będą zawierać następujące ważne dane: temat e-maila, adres odbiorcy e-maila, komunikat o błędzie i pomocne odnośniki ułatwiające rozwiązanie problemu.','Notify when'=>'Powiadom, jeśli','The initial email sending request fails'=>'Początkowe żądanie wysłania e-maila się nie powiodło','This option is always enabled and will notify you about instant email sending failures.'=>'Ta opcja jest zawsze włączona i zapewni ci niezwłoczne powiadomienia o niepowodzeniach wysyłania e-maili.','The deliverability verification process detects a hard bounce'=>'Proces weryfikacji dostarczenia wykrywa trwałe odrzucenia e-maili','Code Snippets by WPCode'=>'Fragmenty kodu od WPCode','Follow this link to <a href="%s" target="_blank" rel="noopener noreferrer">get a Mailgun API Key</a>. Generate a key in the "Mailgun API Keys" section.'=>'Kliknij ten odnośnik, aby <a href="%s" target="_blank" rel="noopener noreferrer">uzyskać klucz API usługi Mailgun</a>. Wygeneruj klucz w sekcji „Klucze API usługi Mailgun”.','The following DB table is still missing.'=>'Nadal brakuje następującej tabeli bazy danych.' . "\0" . 'Nadal brakuje następujących tabel bazy danych.' . "\0" . 'Nadal brakuje następujących tabel bazy danych.','Error icon'=>'Ikonka błędu','WordPress SEO Toolkit'=>'Zestaw narzędzi SEO do WordPressa','Improve your website\'s SEO ranking with our toolkit.'=>'Skorzystaj z naszego zestawu narzędzi i popraw pozycję swojej witryny internetowej w wynikach wyszukiwania.','The following plugin will be installed for free:'=>'Następująca wtyczka zostanie zainstalowana bezpłatnie:','Mailgun API Key'=>'Klucz API usługi Mailgun','%1$sFollow this link%2$s to get a Mailgun API Key. Generate a key in the "Mailgun API Keys" section.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać klucz API usługi Mailgun. Wygeneruj klucz w sekcji „Klucze API usługi Mailgun”.','The Email Test tab was moved to <a href="%s">WP Mail SMTP > Tools</a>.'=>'Karta Test e-maili została przeniesiona do sekcji <a href="%s">WP Mail SMTP > Narzędzia</a>.','<a href="%s" target="_blank" rel="noopener noreferrer">Upgrade to Pro</a> and get instant alert notifications when they fail.'=>'<a href="%s" target="_blank" rel="noopener noreferrer">Kup Pro</a> i zyskaj dostęp do natychmiastowych powiadomień o nieudanych e-mailach.','Dismiss email alert block'=>'Odrzuć blokadę alertów e-mail','We detected %d failed email in the last 30 days.'=>'Wykryliśmy %d nieudany e-mail w ciągu ostatnich 30 dni.' . "\0" . 'Wykryliśmy %d nieudane e-maile w ciągu ostatnich 30 dni.' . "\0" . 'Wykryliśmy %d nieudanych e-maili w ciągu ostatnich 30 dni.','Get Brevo Now (Free)'=>'Uzyskaj Brevo (bezpłatnie)','We believe in full transparency. The Brevo (formerly Sendinblue) links above are tracking links as part of our partnership with Brevo. We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Wierzymy w pełną przejrzystość. Powyższe odnośniki do usługi Brevo (dawniej Sendinblue) to odnośniki śledzące, które stanowią element naszej współpracy z Brevo. Moglibyśmy polecić niemal każdą usługę SMTP, ale polecamy tylko produkty, które naszym zdaniem zapewnią wartość dodaną naszym użytkownikom.','Brevo'=>'Brevo','Please input the sending domain/subdomain you configured in your Brevo dashboard. More information can be found in our %1$sBrevo documentation%2$s'=>'Wpisz domenę/poddomenę wysyłającą, która została skonfigurowana w kokpicie Brevo. Więcej informacji można znaleźć w naszej %1$sdokumentacji usługi Brevo%2$s','Get Started with Brevo'=>'Rozpocznij korzystanie z usługi Brevo','Read how to set up Brevo'=>'Poznaj sposób konfiguracji usługi Brevo','We believe in full transparency. The Brevo links above are tracking links as part of our partnership with Brevo. We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Wierzymy w pełną przejrzystość. Powyższe odnośniki do usługi Brevo to odnośniki śledzące, które stanowią element naszej współpracy z Brevo. Moglibyśmy polecić niemal każdą usługę SMTP, ale polecamy tylko produkty, które naszym zdaniem zapewnią wartość dodaną naszym użytkownikom.','Please input the sending domain/subdomain you configured in your MailerSend dashboard. More information can be found in our %1$sMailerSend documentation%2$s'=>'Proszę wprowadzić domenę/subdomenę wysyłającą skonfigurowaną w panelu MailerSend. Więcej informacji można znaleźć w naszej %1$sdokumentacji MailerSend%2$s','Future proof your WordPress customizations with the most popular code snippet management plugin for WordPress. Trusted by over 1,500,000+ websites for easily adding code to WordPress right from the admin area.'=>'Przygotuj funkcje dostosowywania swojej witryny na przyszłe wyzwania przy użyciu najpopularniejszej wtyczki do WordPressa umożliwiającej zarządzanie fragmentami kodu. Cieszy się ona zaufaniem administratorów ponad 1 500 000 witryn internetowych, ponieważ umożliwia łatwe dodawanie kodu do WordPressa bezpośrednio z obszaru administratora.','WPCode Pro'=>'WPCode Pro','Duplicator'=>'Duplicator','Leading WordPress backup & site migration plugin. Over 1,500,000+ smart website owners use Duplicator to make reliable and secure WordPress backups to protect their websites. It also makes website migration really easy.'=>'Czołowa wtyczka do WordPressa służąca do tworzenia kopii zapasowych i migracji witryn. Ponad 1 500 000 rozsądnych właścicieli witryn internetowych w WordPressie używa wtyczki Duplicator do ochrony witryn przez tworzenie ich kopii zapasowych. Wtyczka znacznie ułatwia też migrację witryn internetowych.','Duplicator Pro'=>'Duplicator Pro','We\'re sorry, the %name% mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Niestety, usługa pocztowa %name% nie jest dostępna w twoim planie. Kup PRO, aby uzyskać dostęp do tej i innych fantastycznych funkcji.','Top-rated WordPress donation and fundraising plugin. Over 10,000+ non-profit organizations and website owners use Charitable to create fundraising campaigns and raise more money online.'=>'Wysoko oceniana wtyczka do WordPressa służąca do obsługi darowizn i zbiórek pieniężnych. Ponad 10 000 organizacji non profit i właścicieli witryn internetowych używa Charitable do tworzenia kampanii fundraisingowych i zbierania pieniędzy online.','WPCode Lite'=>'WPCode Lite','Enable Smart Routing'=>'Włącz inteligentne przekierowywanie','Send with'=>'Wyślij przy użyciu połączenia','WooCommerce Emails (SendLayer)'=>'E-maile WooCommerce (SendLayer)','if the following conditions are met...'=>'jeśli są spełnione następujące warunki...','Arrow Up'=>'Strzałka w górę','Arrow Down'=>'Strzałka w dół','Contains'=>'Zawiera','Order'=>'Kolejność','And'=>'i','Is'=>'Jest','or'=>'lub','Add New Group'=>'Dodaj nową grupę','Contact Emails (SMTP.com)'=>'Kontaktowe adresy e-mail (SMTP.com)','Initiator'=>'Inicjator','Light bulb icon'=>'Ikonka żarówki','Friendly reminder, your Primary Connection will be used for all emails that do not match the conditions above.'=>'Pamiętaj, że w przypadku każdego e-maila, który nie spełnia powyższych warunków, będzie używane połączenie podstawowe.','Primary'=>'Podstawowe','WP Core (%s)'=>'Rdzeń WP (%s)','It looks like we can\'t remove OAuth connection.'=>'Wygląda na to, że nie można usunąć połączenia OAuth.','Remove OAuth Connection'=>'Usuń połączenie OAuth','There was an error while processing the authentication request. The state key is invalid. Please try again.'=>'Podczas przetwarzania żądania uwierzytelnienia wystąpił błąd. Klucz stanu jest nieprawidłowy. Spróbuj ponownie.','Additional Connections'=>'Dodatkowe połączenia','Backup Connection'=>'Połączenie zapasowe','Smart Routing'=>'Inteligentne przekierowywanie','With additional connections you can...'=>'Dzięki dodatkowym połączeniom możesz...','Set a Backup Connection'=>'Ustawić połączenie zapasowe','Use mailers for different purposes'=>'Używać usług pocztowych do różnych celów','Create advanced routing rules'=>'Tworzyć zaawansowane reguły przekierowywania','Primary Connection'=>'Połączenie podstawowe','Once you add an <a href="%s">additional connection</a>, you can select it here.'=>'Po zdefiniowaniu <a href="%s">dodatkowego połączenia</a> możesz je wybrać tutaj.','Don’t worry about losing emails. Add an additional connection, then set it as your Backup Connection. Emails that fail to send with the Primary Connection will be sent via the selected Backup Connection. <a href="%s" target="_blank" rel="noopener noreferrer">Upgrade to WP Mail SMTP Pro!</a>'=>'Nie martw się o utratę e-maili. Skonfiguruj dodatkowe połączenie, a następnie ustaw je jako połączenie zapasowe. E-maile, których nie uda się wysłać przy użyciu połączenia podstawowego, zostaną wysłane za pośrednictwem wybranego połączenia zapasowego. <a href="%s" target="_blank" rel="noopener noreferrer">Kup WP Mail SMTP Pro!</a>','Instant Email Alerts'=>'Natychmiastowe alerty e-mail','Get notifications via email, SMS, Slack, or webhook when emails fail to send.'=>'W przypadku, gdy nie uda się wysłać e-maila, możesz otrzymać powiadomienie pocztą e-mail, SMS-em, na Slacku lub przez webhook.','Complete Email Reports'=>'Pełne raporty o e-mailach','See the delivery status, track opens and clicks, and create deliverability graphs.'=>'Oglądaj status dostarczenia, śledź otwarcia i kliknięcia oraz twórz wykresy dostarczenia.','Enable these powerful logging features for more control of your WordPress emails.'=>'Włącz te zaawansowane funkcje rejestrowania, aby mieć większą kontrolę nad e-mailami w WordPressie.','Store the content for all sent emails'=>'Przechowuj treść wszystkich wysłanych e-maili','This option must be enabled if you\'d like to be able to resend emails. Please be aware that all email content will be stored in your WordPress database. This may include sensitive data, passwords, and personal details.'=>'Ta opcja musi być włączona, jeśli chcesz mieć możliwość ponownego wysyłania e-maili. Pamiętaj, że cała treść e-maili będzie przechowywana w twojej bazie danych WordPressa. Może ona obejmować dane poufne, hasła i dane osobowe.','Save file attachments sent from WordPress'=>'Zapisuj pliki załączników wysyłane z WordPressa','All file attachments sent from your site will be saved to the WordPress Uploads folder. Please note that this may reduce available disk space on your server.'=>'Wszystkie pliki załączników wysłane z twojej witryny będą zapisywane w katalogu WordPressa z przesłanymi plikami. Pamiętaj, że może to zmniejszyć ilość miejsca na dysku dostępną na serwerze.','Track when an email is opened'=>'Śledź otwarcia e-maili','See which emails were opened by the recipients. Email open tracking works with emails that are sent in HTML format.'=>'Zobacz, które e-maile zostały otwarte przez odbiorcę. Śledzenie otwarcia e-maili działa w przypadku e-maili wysłanych w formacie HTML.','Track when a link in an email is clicked'=>'Śledź kliknięcia odnośnika w e-mailu','See which links were clicked in emails sent from your WordPress site. Click tracking works with emails that are sent in HTML format.'=>'Zobacz, które odnośniki w e-mailach wysłanych z twojej witryny w WordPressie zostały kliknięte. Śledzenie kliknięcia działa w przypadku e-maili wysłanych w formacie HTML.','Backtrace:'=>'Ślad:','[%1$d] %2$s called at [%3$s:%4$s]'=>'[%1$d] Funkcja %2$s wywołana: [%3$s:%4$s]','Events Retention Period'=>'Okres przechowywania zdarzeń','Forever'=>'Cały czas','Debug events older than the selected period will be permanently deleted from the database.'=>'Zdarzenia debugowania starsze od wybranego okresu będą trwale usuwane z bazy danych.','1 Week'=>'1 tydzień','1 Month'=>'1 miesiąc','3 Months'=>'3 miesiące','6 Months'=>'6 miesięcy','1 Year'=>'1 rok','Unknown.'=>'Nieznane.','Missing DB tables were created successfully.'=>'Utworzono brakujące tabele bazy danych.','Some DB Tables are still missing.'=>'Nadal brakuje niektórych tabel bazy danych.','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it seems they are missing. Please try to <a href="%1$s" target="_self" aria-label="%2$s" rel="noopener noreferrer">%3$s</a>. If this issue persists, please contact our support.'=>'Wtyczka WP Mail SMTP używa własnych tabel bazy danych w przypadku niektórych swoich funkcji. Aby działało to poprawnie, powinny być utworzone tabele własne, a wygląda na to, że ich brakuje. Spróbuj <a href="%1$s" target="_self" aria-label="%2$s" rel="noopener noreferrer">%3$s</a>. Jeśli problem nie ustąpi, skontaktuj się z naszym zespołem pomocy technicznej.','Go to WP Mail SMTP settings page.'=>'Przejdź do strony ustawień wtyczki WP Mail SMTP.','create the missing DB tables by clicking on this link'=>'utworzyć brakujące tabele bazy danych, klikając ten odnośnik','<strong>Table:</strong> %1$s. <strong>Reason:</strong> %2$s'=>'<strong>Tabela:</strong> %1$s. <strong>Przyczyna:</strong> %2$s','%d Day'=>'%d dzień' . "\0" . '%d dni' . "\0" . '%d dni','%1$sFollow this link%2$s to get a Private API Key from Mailgun.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać prywatny klucz API z usługi Mailgun.','Configure Email Logs'=>'Skonfiguruj dzienniki e-maili','Enter the email addresses (3 max) you’d like to use to receive alerts when email sending fails. Read our documentation on setting up email alerts.'=>'Wpisz adresy e-mail (maksymalnie 3), których chcesz używać do otrzymywania alertów w przypadku, gdy wysłanie e-maila się nie powiedzie. Zapoznaj się z naszą dokumentacją dotyczącą konfigurowania alertów e-mail.','Email Alerts'=>'Alerty e-mail','Slack'=>'Slack','Paste in the Slack webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up Slack alerts.'=>'Wklej adres URL webhooka Slack, którego chcesz używać do otrzymywania alertów w przypadku, gdy wysłanie e-maila się nie powiedzie. Zapoznaj się z naszą dokumentacją dotyczącą konfigurowania alertów Slack.','Slack Alerts'=>'Alerty Slack','Webhook URL'=>'Adres URL webhooka','SMS via Twilio'=>'SMS przez Twilio','To receive SMS alerts, you’ll need a Twilio account. Read our documentation to learn how to set up Twilio SMS, then enter your connection details below.'=>'Do otrzymywania alertów SMS potrzebne jest konto Twilio. Zapoznaj się z naszą dokumentacją, aby poznać sposób konfigurowania SMS-ów w Twilio, a następnie wpisz poniżej dane połączenia.','SMS via Twilio Alerts'=>'Alerty SMS przez Twilio','Twilio Account ID'=>'Identyfikator konta Twilio','Twilio Auth Token'=>'Token autoryzacji Twilio','From Phone Number'=>'Numer telefonu nadawcy','To Phone Number'=>'Numer telefonu odbiorcy','Webhook'=>'Webhook','Paste in the webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up webhook alerts.'=>'Wklej adres URL webhooka, którego chcesz używać do otrzymywania alertów w przypadku, gdy wysłanie e-maila się nie powiedzie. Zapoznaj się z naszą dokumentacją dotyczącą konfigurowania alertów przez webhook.','Webhook Alerts'=>'Alerty przez webhook','Or deactivate "SMTP" module in Branda > Emails > SMTP.'=>'Możesz też wyłączyć moduł „SMTP” w sekcji Branda > E-maile > SMTP.','WP Mail SMTP has detected incorrect "wp_mail" function location. Usually, this means that emails will not be sent successfully!'=>'Wtyczka WP Mail SMTP wykryła niepoprawną lokalizację funkcji „wp_mail”. Zwykle oznacza to, że e-maile nie zostaną wysłane!','It looks like the "%s" plugin is overwriting the "wp_mail" function. Please reach out to the plugin developer on how to disable or remove the "wp_mail" function overwrite to prevent conflicts with WP Mail SMTP.'=>'Wygląda na to, że wtyczka „%s” powoduje zastępowanie funkcji „wp_mail”. Skontaktuj się z deweloperem tej wtyczki, aby się dowiedzieć, jak wyłączyć lub usunąć zastępowanie funkcji „wp_mail” w celu zapobieżenia konfliktom z wtyczką WP Mail SMTP.','It looks like the "%s" must-use plugin is overwriting the "wp_mail" function. Please reach out to your hosting provider on how to disable or remove the "wp_mail" function overwrite to prevent conflicts with WP Mail SMTP.'=>'Wygląda na to, że obowiązkowa wtyczka „%s” powoduje zastępowanie funkcji „wp_mail”. Skontaktuj się z dostawcą hostingu, aby się dowiedzieć, jak wyłączyć lub usunąć zastępowanie funkcji „wp_mail” w celu zapobieżenia konfliktom z wtyczką WP Mail SMTP.','It looks like it\'s overwritten in the "wp-config.php" file. Please reach out to your hosting provider on how to disable or remove the "wp_mail" function overwrite to prevent conflicts with WP Mail SMTP.'=>'Wygląda na to, że została ona zastąpiona w pliku „wp-config.php”. Skontaktuj się z dostawcą hostingu, aby się dowiedzieć, jak wyłączyć lub usunąć zastępowanie funkcji „wp_mail” w celu zapobieżenia konfliktom z wtyczką WP Mail SMTP.','Current function path: %s'=>'Bieżąca ścieżka funkcji: %s','Let’s see how many emails you’ve sent with WP Mail SMTP.'=>'Zobaczmy, ile e-maili udało ci się wysłać za pomocą wtyczki WP Mail SMTP.','There was an error while processing the authentication request. The nonce is invalid. Please try again.'=>'Podczas przetwarzania żądania uwierzytelnienia wystąpił błąd. Kod jednorazowy jest nieprawidłowy. Spróbuj ponownie.','There was an error while processing the authentication request. The authorization code is missing. Please try again.'=>'Podczas przetwarzania żądania uwierzytelnienia wystąpił błąd. Brak kodu autoryzacji. Spróbuj ponownie.','Alerts'=>'Ostrzeżenia','SendLayer'=>'SendLayer','Follow this link to get an API Key from SendLayer: %s.'=>'Kliknij ten odnośnik, aby uzyskać klucz API usługi SendLayer: %s.','%1$sFollow this link%2$s to get an API Key for SendLayer.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać klucz API usługi SendLayer.','Get Started with SendLayer'=>'Rozpocznij korzystanie z usługi SendLayer','Read how to set up SendLayer'=>'Poznaj sposób konfiguracji usługi SendLayer','Get WP Mail SMTP Pro'=>'Pobierz wtyczkę WP Mail SMTP Pro','Go to WPMailSMTP.com documentation page'=>'Przejdź do strony dokumentacji na WPMailSMTP.com','Docs'=>'Dokumenty','Verify your <a href="%1$s" target="_blank" rel="noopener noreferrer">Domain Name</a> is correct.'=>'Sprawdź, czy <a href="%1$s" target="_blank" rel="noopener noreferrer">nazwa domeny</a> jest poprawna.','Verify your domain Region is correct.'=>'Sprawdź, czy region domeny jest poprawny.','Read how to set up SendGrid'=>'Poznaj sposób konfiguracji usługi SendGrid','Go to your Mailgun account and verify that your <a href="%1$s" target="_blank" rel="noopener noreferrer">Mailgun API Key</a> is correct.'=>'Przejdź do konta Mailgun i sprawdź, czy masz poprawny <a href="%1$s" target="_blank" rel="noopener noreferrer">klucz API usługi Mailgun</a>.','%1$sFollow this link%2$s to get an API Key for MailerSend.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać klucz API dla MailerSend.','The best WordPress eCommerce plugin for selling digital downloads. Start selling eBooks, software, music, digital art, and more within minutes. Accept payments, manage subscriptions, advanced access control, and more.'=>'Najlepsza wtyczka e-handlu do WordPressa, służąca do sprzedawania pobieranych treści cyfrowych. Zacznij sprzedawać e-booki, oprogramowanie, muzykę, sztukę cyfrową i inne treści w ciągu minut. Możesz przyjmować płatności, zarządzać subskrypcjami, szczegółowo kontrolować dostęp i nie tylko.','Sugar Calendar Lite'=>'Sugar Calendar Lite','A simple & powerful event calendar plugin for WordPress that comes with all the event management features including payments, scheduling, timezones, ticketing, recurring events, and more.'=>'Prosta i wydajna wtyczka kalendarza do WordPressa, która zawiera wszystkie potrzebne funkcje zarządzania wydarzeniami, w tym płatności, harmonogram, strefy czasowe, bilety, wydarzenia cykliczne i nie tylko.','Sugar Calendar'=>'Sugar Calendar','Could not activate the plugin. Plugin is not whitelisted.'=>'Nie udało się włączyć wtyczki. Wtyczka nie znajduje się na białej liście.','Could not install the plugin. Plugin is not whitelisted.'=>'Nie udało się zainstalować wtyczki. Wtyczka nie znajduje się na białej liście.','On this page, you can view different plugin debugging events and email sending errors.'=>'Na tej stronie można przeglądać różne zdarzenia debugowania wtyczki i błędy wysyłania e-maili.','Visit <a href="%s" target="_blank" rel="noopener noreferrer">our documentation</a> for additional tips on how to resolve this error.'=>'W celu uzyskania dodatkowych wskazówek dotyczących naprawiania tego błędu zajrzyj do <a href="%s" target="_blank" rel="noopener noreferrer">naszej dokumentacji</a>.','Could not install the plugin. You don\'t have permission to activate plugins.'=>'Nie można było zainstalować wtyczki. Nie masz uprawnień do włączania wtyczek.','Or enable "Do not change email sender by default" setting in Settings > Email template > Sender (tab).'=>'Możesz też kliknąć Ustawienia > Szablon e-maila > (karta) Nadawca i włączyć opcję „Nie zmieniaj domyślnie nadawcy e-maili”.','If you create a test email on this page, it will still be sent.'=>'Jeśli utworzysz e-mail testowy na tej stronie, zostanie on wysłany.','Your site is running an <strong>old version</strong> of WordPress that is no longer supported by WP Mail SMTP. Please update your WordPress site to at least version <strong>%s</strong>.'=>'Twoja witryna korzysta ze <strong>starej wersji</strong> WordPressa, która już nie jest obsługiwana przez wtyczkę WP Mail SMTP. Zaktualizuj witrynę WordPressa co najmniej do wersji <strong>%s</strong>.','<strong>WP Mail SMTP plugin is disabled</strong> on your site until WordPress is updated to the required version.'=>'<strong>Wtyczka WP Mail SMTP w twojej witrynie została wyłączona</strong> do czasu zaktualizowania WordPressa do wymaganej wersji.','Visit Site'=>'Przejdź do witryny','SearchWP'=>'SearchWP','The most advanced WordPress search plugin. Customize your WordPress search algorithm, reorder search results, track search metrics, and everything you need to leverage search to grow your business.'=>'Najbardziej zaawansowana wtyczka wyszukiwania do WordPressa. Umożliwia dostosowywanie algorytmu wyszukiwania w WordPressie, zmianę kolejności wyników wyszukiwania i śledzenie wskaźników wyszukiwania oraz udostępnia wszystkie funkcje potrzebne do rozwijania działalności przy użyciu wyszukiwarki.','AffiliateWP'=>'AffiliateWP','The #1 affiliate management plugin for WordPress. Easily create an affiliate program for your eCommerce store or membership site within minutes and start growing your sales with the power of referral marketing.'=>'Najlepsza wtyczka do WordPressa służąca do zarządzania partnerami. Łatwo utwórz program partnerski do swojego sklepu internetowego lub witryny członkowskiej w czasie rzędu minut i zacznij powiększać sprzedaż dzięki potędze marketingu rekomendacji.','WP Simple Pay'=>'WP Simple Pay','The #1 Stripe payments plugin for WordPress. Start accepting one-time and recurring payments on your WordPress site without setting up a shopping cart. No code required.'=>'Najlepsza wtyczka do WordPressa umożliwiająca obsługę płatności Stripe. Zacznij przyjmować płatności jednorazowe i cykliczne w swojej witrynie w WordPressie, nie zakładając koszyka. Nie musisz pisać żadnego kodu.','WP Simple Pay Pro'=>'WP Simple Pay Pro','Easy Digital Downloads'=>'Easy Digital Downloads','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">SparkPost documentation</a>.'=>'Aby rozpocząć, zapoznaj się z <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentacją usługi SparkPost</a>.','SparkPost'=>'SparkPost','Follow this link to get an API Key from SparkPost: %s.'=>'Kliknij ten odnośnik, aby uzyskać klucz API usługi SparkPost: %s.','Select your SparkPost account region.'=>'Wybierz region swojego konta SparkPost.','<a href="%s" rel="" target="_blank">More information</a> on SparkPost.'=>'<a href="%s" rel="" target="_blank">Więcej informacji</a> na temat SparkPost.','<a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost</a> is a transactional email provider that\'s trusted by big brands and small businesses. It sends more than 4 trillion emails each year and reports 99.9%% uptime. You can get started with the free test account that lets you send up to 500 emails per month.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost</a> to dostawca transakcyjnych usług e-mail, któremu zaufały zarówno duże marki, jak i małe firmy. Każdego roku wysyła on ponad 4 biliony e-maili i notuje czas dostępności na poziomie 99,9%%. Możesz zacząć od bezpłatnego konta testowego, które umożliwia wysyłanie do 500 e-maili miesięcznie.','SparkPost API failed.'=>'Niepowodzenie SparkPost API.','Go to your <a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost account</a> or <a href="%2$s" target="_blank" rel="noopener noreferrer">SparkPost EU account</a> and verify that your API key is correct.'=>'Przejdź do konta <a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost</a> lub <a href="%2$s" target="_blank" rel="noopener noreferrer">SparkPost EU</a> i sprawdź, czy masz poprawny klucz API.','Verify that your API key has "Transmissions: Read/Write" permission.'=>'Sprawdź, czy klucz API ma uprawnienie „Transmisje: odczyt/zapis”.','Verify that your SparkPost account region is selected in WP Mail SMTP settings.'=>'Sprawdź, czy w ustawieniach wtyczki WP Mail SMTP wybrano region twojego konta SparkPost.','Google / Gmail'=>'Google / Gmail','365 / Outlook'=>'365 / Outlook','API Key:'=>'Klucz API:','Region:'=>'Region:','This setting is already configured with the WP Mail SMTP constant. To change it, please edit or remove the <code></code> constant in your <code>wp-config.php</code> file.'=>'To ustawienie już zostało skonfigurowane za pomocą stałej wtyczki WP Mail SMTP. Aby je zmienić, zmodyfikuj lub usuń stałą <code></code> znajdującą się w pliku <code>wp-config.php</code>.','Your mailer is already configured in a WP Mail SMTP constant, so the options below have been disabled. To change your mailer, please edit or remove the <code>WPMS_MAILER</code> constant in your <code>wp-config.php</code> file.'=>'Twoja usługa pocztowa już jest skonfigurowana w stałej wtyczki WP Mail SMTP, więc poniższe opcje zostały wyłączone. Aby zmienić usługę pocztową, zmodyfikuj lub usuń stałą <code>WPMS_MAILER</code> znajdującą się w pliku <code>wp-config.php</code>.','FluentSMTP'=>'FluentSMTP','Microsoft 365 / Outlook'=>'Microsoft 365 / Outlook','Select your SparkPost account region. %1$sMore information%2$s on SparkPost.'=>'Wybierz region konta SparkPost. %1$sWięcej informacji%2$s na temat usługi SparkPost.','Read how to set up SparkPost'=>'Poznaj sposób konfiguracji usługi SparkPost','%1$sFollow this link%2$s to get an API Key for SparkPost.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać klucz API usługi SparkPost.','<strong><a href="%s" target="_blank" rel="noopener noreferrer">SMTP.com</a> is one of our recommended mailers.</strong> It\'s a transactional email provider that\'s currently used by 100,000+ businesses. SMTP.com is an established brand that\'s been offering email services for more than 20 years.<br><br>SMTP.com offers a free 30-day trial that allows you to send up to 50,000 emails.'=>'<strong><a href="%s" target="_blank" rel="noopener noreferrer">SMTP.com</a> to jedna z polecanych przez nas usług pocztowych.</strong> Jest to dostawca transakcyjnych usług e-mail, z którego obecnie korzysta ponad 100 000 firm. SMTP.com to uznana marka, która oferuje usługi e-mail od ponad 20 lat.<br><br>SMTP.com oferuje bezpłatny 30-dniowy okres próbny, w czasie którego można wysłać do 50 000 e-maili.','To get started, read our <a href="%s" target="_blank" rel="noopener noreferrer">SMTP.com documentation</a>.'=>'Aby rozpocząć, zapoznaj się z <a href="%s" target="_blank" rel="noopener noreferrer">dokumentacją usługi SMTP.com</a>.','The Other SMTP option lets you send emails through an SMTP server instead of using a provider\'s API. This is easy and convenient, but it\'s less secure than the other mailers. Please note that your provider may not allow you to send a large number of emails. In that case, please use a different mailer.<br><br>To get started, read our <a href="%s" target="_blank" rel="noopener noreferrer">Other SMTP documentation</a>.'=>'Opcja Inne SMTP umożliwia wysyłanie e-maili za pośrednictwem serwera SMTP — nie trzeba korzystać z interfejsu API dostawcy. Jest to łatwe i wygodne rozwiązanie, ale mniej bezpieczne niż w inne usługi pocztowe. Pamiętaj, że twój dostawca może nie zezwalać na wysyłanie wielu e-maili. W takim przypadku użyj innej usługi pocztowej.<br><br>Aby rozpocząć, zapoznaj się z <a href="%s" target="_blank" rel="noopener noreferrer">dokumentacją usługi Inne SMTP</a>.','<strong><a href="%1$s" target="_blank" rel="noopener noreferrer">Brevo</a> (formerly Sendinblue) is one of our recommended mailers.</strong> It\'s a transactional email provider with scalable price plans, so it\'s suitable for any size of business.<br><br>If you\'re just starting out, you can use Brevo\'s free plan to send up to 300 emails a day. You don\'t need to use a credit card to try it out. When you\'re ready, you can upgrade to a higher plan to increase your sending limits.'=>'<strong><a href="%1$s" target="_blank" rel="noopener noreferrer">Brevo</a> (dawniej Sendinblue) jest jedną z polecanych przez nas usług pocztowych.</strong> Jest to dostawca transakcyjnych usług e-mail ze skalowalnymi planami cenowymi — a zatem odpowiedni dla firm dowolnej wielkości.<br><br>Jeśli dopiero zaczynasz, możesz skorzystać z bezpłatnego planu Brevo, który umożliwia wysyłanie do 300 e-maili dziennie. Nie musisz używać karty kredytowej, aby wypróbować tę usługę. A gdy przyjdzie na to czas, możesz ulepszyć plan, aby uzyskać większe limity wysyłania.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Brevo documentation</a>.'=>'Na początek zapoznaj się z naszą <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentacją usługi Brevo</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">SendGrid</a> is a popular transactional email provider that sends more than 35 billion emails every month. If you\'re just starting out, the free plan allows you to send up to 100 emails each day without entering your credit card details.<br><br>To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">SendGrid documentation</a>.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">SendGrid</a> to popularny dostawca transakcyjnych usług e-mail, który każdego miesiąca obsługuje wysyłanie ponad 35 miliardów e-maili. Jeśli dopiero zaczynasz, bezpłatny plan pozwala na wysłanie do 100 e-maili dziennie bez podawania danych karty kredytowej.<br><br>Aby rozpocząć, zapoznaj się z <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentacją usługi SendGrid</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Postmark</a> is a transactional email provider that offers great deliverability and accessible pricing for any business. You can start out with the free trial that allows you to send 100 test emails each month via its secure API.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Postmark</a> to dostawca transakcyjnych usług e-mail, który oferuje znakomitą skuteczność dostarczania i ceny przystępne dla każdej firmy. Możesz zacząć od bezpłatnej wersji próbnej, która umożliwia wysyłanie 100 e-maili testowych miesięcznie za pośrednictwem bezpiecznego interfejsu API.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Postmark documentation</a>.'=>'Aby rozpocząć, zapoznaj się z <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentacją usługi Postmark</a>.','Postmark'=>'Postmark','Follow this link to get a Server API Token from Postmark: %s.'=>'Kliknij ten odnośnik, aby uzyskać token API serwera od Postmark: %s.','Get Server API Token'=>'Uzyskaj token API serwera','Message Stream ID is <strong>optional</strong>. By default <strong>outbound</strong> (Default Transactional Stream) will be used. More information can be found in our <a href="%s" target="_blank" rel="noopener noreferrer">Postmark documentation</a>.'=>'Identyfikator strumienia wiadomości jest <strong>opcjonalny</strong>. Domyślnie będzie używany strumień <strong>wychodzący</strong> (domyślny strumień transakcyjny). Więcej informacji można znaleźć w <a href="%s" target="_blank" rel="noopener noreferrer">dokumentacji usługi Postmark</a>.','Server API Token:'=>'Token API serwera:','Message Stream ID:'=>'Identyfikator strumienia wiadomości:','<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailgun</a> is a transactional email provider that offers a generous 3-month free trial. After that, it offers a \'Pay As You Grow\' plan that allows you to pay for what you use without committing to a fixed monthly rate.<br><br>To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Mailgun documentation</a>.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailgun</a> to dostawca transakcyjnych usług e-mail, który szczodrze oferuje bezpłatny 3-miesięczny okres próbny. Potem można skorzystać z oferty planu „Płatności w miarę rozwoju”, dzięki któremu można płacić tylko za faktyczne wykorzystanie — bez zobowiązywania się do ustalonych comiesięcznych opłat.<br><br>Aby rozpocząć, zapoznaj się z <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentacją usługi Mailgun</a>.','Export logs to CSV, XLSX, or EML'=>'Eksportuj dzienniki w formacie CSV, XLSX lub EML','Hide plugin announcements and update details.'=>'Ukryj ogłoszenia dotyczące wtyczki i szczegóły aktualizacji.','Hide warnings alerting of email delivery errors.'=>'Ukryj ostrzeżenia informujące o błędach dostarczania e-maili.','Hide the WP Mail SMTP Dashboard Widget.'=>'Ukryj widżet WP Mail SMTP przeznaczony do kokpitu.','Stop sending all emails'=>'Przestań wysyłać wszystkie e-maile','Full log of background update results which includes information about WordPress core, plugins, themes, and translations updates. Only sent when you are using a development version of WordPress. Sent to the site or network admin.'=>'Pełny dziennik wyników aktualizacji w tle, który zawiera informacje o aktualizacjach rdzenia WordPressa, wtyczek, motywów i tłumaczeń. Wysyłany tylko w przypadku, gdy korzystasz z wersji WordPressa dla deweloperów. Wiadomość wysyłana do administratora witryny lub sieci.','New User'=>'Nowy użytkownik','Created (Admin)'=>'Utworzono (dla administratora)','A new user was created. Sent to the site admin.'=>'Utworzono nowego użytkownika. Wiadomość wysyłana do administratora witryny.','Created (User)'=>'Utworzono (dla użytkownika)','A new user was created. Sent to the new user.'=>'Utworzono nowego użytkownika. Wiadomość wysyłana do nowego użytkownika.','Invited To Site'=>'Zaproszono do witryny','A new user was invited to a site from Users -> Add New -> Add New User. Sent to the invited user.'=>'Nowy użytkownik został zaproszony do witryny z poziomu menu Użytkownicy -> Dodaj nowego -> Dodaj nowego użytkownika. Wiadomość wysyłana do zaproszonego użytkownika.','Created On Site'=>'Utworzono w witrynie','A new user account was created. Sent to Network Admin.'=>'Utworzono nowe konto użytkownika. Wiadomość wysyłana do administratora sieci.','Added / Activated on Site'=>'Dodano/aktywowano w witrynie','A user has been added, or their account activation has been successful. Sent to the user, that has been added/activated.'=>'Użytkownik został dodany lub aktywacja jego konta się powiodła. Wiadomość wysyłana do dodanego/aktywowanego użytkownika.','New Site'=>'Nowa witryna','User Created Site'=>'Użytkownik utworzył witrynę','User registered for a new site. Sent to the site admin.'=>'Użytkownik zarejestrował nową witrynę. Wiadomość wysyłana do administratora witryny.','Network Admin: User Activated / Added Site'=>'Administrator sieci: użytkownik włączył/dodał witrynę','User activated their new site, or site was added from Network Admin -> Sites -> Add New. Sent to Network Admin.'=>'Użytkownik włączył nową witrynę lub witryna została dodana z poziomu menu Administrator sieci -> Witryny -> Dodaj nową. Wiadomość wysyłana do administratora sieci.','Site Admin: Activated / Added Site'=>'Administrator witryny: włączono/dodano witrynę','User activated their new site, or site was added from Network Admin -> Sites -> Add New. Sent to Site Admin.'=>'Użytkownik włączył nową witrynę lub witryna została dodana z poziomu menu Administrator sieci -> Witryny -> Dodaj nową. Wiadomość wysyłana do administratora witryny.','Server API Token'=>'Token API serwera','Message Stream ID'=>'Identyfikator strumienia wiadomości','%1$sFollow this link%2$s to get a Server API Token for Postmark.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać token API serwera do usługi Postmark.','Message Stream ID is <strong>optional</strong>. By default <strong>outbound</strong> (Default Transactional Stream) will be used. More information can be found in our %1$sPostmark documentation%2$s.'=>'Identyfikator strumienia wiadomości jest <strong>opcjonalny</strong>. Domyślnie używane jest ustawienie <strong>outbound</strong> (domyślny strumień transakcyjny). Więcej informacji można znaleźć w naszej %1$sdokumentacji usługi Postmark%2$s.','Read how to set up Postmark'=>'Poznaj sposób konfiguracji usługi Postmark','Amazon SES requires an SSL certificate, and so is not currently compatible with your site. Please contact your host to request a SSL certificate, or check out '=>'Usługa Amazon SES wymaga certyfikatu SSL, a więc obecnie nie jest zgodna z twoją witryną. Skontaktuj się z firmą hostingową, aby poprosić o certyfikat SSL, lub zapoznaj się z ','WPBeginner\'s tutorial on how to set up SSL'=>'poradnikiem WPBeginner dotyczącym konfigurowania protokołu SSL','If you\'d prefer not to set up SSL, or need an SMTP solution in the meantime, please go back and select a different mailer option.'=>'Jeśli wolisz nie konfigurować protokołu SSL lub w międzyczasie potrzebujesz rozwiązania SMTP, cofnij się i wybierz inną usługę pocztową.','Outlook / 365 requires an SSL certificate, and so is not currently compatible with your site. Please contact your host to request a SSL certificate, or check out '=>'Program Outlook/365 wymaga certyfikatu SSL, a więc obecnie nie jest zgodny z twoją witryną. Skontaktuj się z firmą hostingową, aby poprosić o certyfikat SSL, lub zapoznaj się z ','Comments'=>'Komentarze','Awaiting Moderation'=>'Oczekiwanie na moderację','Comment is awaiting moderation. Sent to the site admin and post author if they can edit comments.'=>'Komentarz oczekuje na moderację. Wiadomość wysyłana do administratora witryny i autora wpisu, jeśli może on edytować komentarze.','Published'=>'Opublikowano','Comment has been published. Sent to the post author.'=>'Komentarz został opublikowany. Wiadomość wysyłana do autora wpisu.','Change of Admin Email'=>'Zmiana adresu e-mail administratora','Site Admin Email Change Attempt'=>'Próba zmiany adresu e-mail administratora witryny','Change of site admin email address was attempted. Sent to the proposed new email address.'=>'Podjęto próbę zmiany adresu e-mail administratora witryny. Wiadomość wysyłana na proponowany nowy adres e-mail.','Site Admin Email Changed'=>'Zmieniono adres e-mail administratora witryny','Site admin email address was changed. Sent to the old site admin email address.'=>'Adres e-mail administratora witryny został zmieniony. Wiadomość wysyłana na stary adres e-mail administratora witryny.','Network Admin Email Change Attempt'=>'Próba zmiany adresu e-mail administratora sieci','Change of network admin email address was attempted. Sent to the proposed new email address.'=>'Podjęto próbę zmiany adresu e-mail administratora sieci. Wiadomość wysyłana na proponowany nowy adres e-mail.','Network Admin Email Changed'=>'Zmieniono adres e-mail administratora sieci','Network admin email address was changed. Sent to the old network admin email address.'=>'Adres e-mail administratora sieci został zmieniony. Wiadomość wysyłana na stary adres e-mail administratora sieci.','Change of User Email or Password'=>'Zmiana adresu e-mail lub hasła użytkownika','Reset Password Request'=>'Prośba o zresetowanie hasła','User requested a password reset via "Lost your password?". Sent to the user.'=>'Użytkownik poprosił o zresetowanie hasła za pomocą funkcji „Nie pamiętasz hasła?”. Wiadomość wysyłana do użytkownika.','Password Reset Successfully'=>'Zresetowano hasło','User reset their password from the password reset link. Sent to the site admin.'=>'Użytkownik zresetował hasło za pomocą odnośnika do resetowania hasła. Wiadomość wysyłana do administratora witryny.','Password Changed'=>'Zmieniono hasło','User changed their password. Sent to the user.'=>'Użytkownik zmienił hasło. Wiadomość wysyłana do użytkownika.','Email Change Attempt'=>'Próba zmiany adresu e-mail','User attempted to change their email address. Sent to the proposed new email address.'=>'Użytkownik próbował zmienić swój adres e-mail. Wiadomość wysyłana na proponowany nowy adres e-mail.','Email Changed'=>'Zmieniono adres e-mail','User changed their email address. Sent to the user.'=>'Użytkownik zmienił swój adres e-mail. Wiadomość wysyłana do użytkownika.','Personal Data Requests'=>'Prośby dotyczące danych osobowych','User Confirmed Export / Erasure Request'=>'Użytkownik potwierdził prośbę o eksport/skasowanie','User clicked a confirmation link in personal data export or erasure request email. Sent to the site or network admin.'=>'Użytkownik kliknął odnośnik potwierdzający w e-mailu dotyczącym prośby o wyeksportowanie lub skasowanie danych osobowych. Wiadomość wysyłana do administratora witryny lub sieci.','Admin Erased Data'=>'Administrator skasował dane','Site admin clicked "Erase Personal Data" button next to a confirmed data erasure request. Sent to the requester email address.'=>'Administrator witryny kliknął przycisk „Skasuj dane osobowe” obok potwierdzonej prośby o skasowanie danych. Wiadomość wysyłana na adres e-mail autora prośby.','Admin Sent Link to Export Data'=>'Administrator wysłał odnośnik do eksportu danych','Site admin clicked "Email Data" button next to a confirmed data export request. Sent to the requester email address.'=>'Administrator witryny kliknął przycisk „Wyślij e-mail z danymi” obok potwierdzonej prośby o wyeksportowanie danych. Wiadomość wysyłana na adres e-mail autora prośby.','Disabling this option will block users from being able to export their personal data, as they will not receive an email with a link.'=>'Wyłączenie tej opcji uniemożliwi użytkownikom eksportowanie danych osobowych, ponieważ nie otrzymają e-maila z odnośnikiem.','Automatic Updates'=>'Automatyczne aktualizacje','Plugin Status'=>'Status wtyczki','Completion or failure of a background automatic plugin update. Sent to the site or network admin.'=>'Ukończenie lub niepowodzenie automatycznej aktualizacji wtyczki w tle. Wiadomość wysyłana do administratora witryny lub sieci.','Theme Status'=>'Status motywu','Completion or failure of a background automatic theme update. Sent to the site or network admin.'=>'Ukończenie lub niepowodzenie automatycznej aktualizacji motywu w tle. Wiadomość wysyłana do administratora witryny lub sieci.','WP Core Status'=>'Status rdzenia WP','Completion or failure of a background automatic core update. Sent to the site or network admin.'=>'Ukończenie lub niepowodzenie automatycznej aktualizacji rdzenia w tle. Wiadomość wysyłana do administratora witryny lub sieci.','Full Log'=>'Pełny dziennik','You currently have the <strong>Default (none)</strong> mailer selected, which won\'t improve email deliverability. Please select <a href="%1$s" target="_blank" rel="noopener noreferrer">any other email provider</a> and use the easy <a href="%2$s">Setup Wizard</a> to configure it.'=>'Masz obecnie wybraną opcję usługi pocztowej <strong>Domyślna (brak)</strong>, która nie zwiększy skuteczności dostarczania e-maili. Wybierz <a href="%1$s" target="_blank" rel="noopener noreferrer">dowolnego innego dostawcę usług e-mail</a> i skonfiguruj go za pomocą łatwego <a href="%2$s">kreatora konfiguracji</a>.','Your Weekly WP Mail SMTP Summary for %s'=>'Twoje cotygodniowe podsumowanie WP Mail SMTP dotyczące witryny %s','WP Mail SMTP Weekly Email Summary'=>'Cotygodniowe podsumowanie e-maili w WP Mail SMTP','WP Mail SMTP Logo'=>'Logo WP Mail SMTP','This email was auto-generated and sent from %1$s. Learn %2$s.'=>'Ten e-mail został wygenerowany automatycznie i wysłany z witryny %1$s. Dowiedz się, %2$s.','how to disable it'=>'jak to wyłączyć','Hi there,'=>'Witaj!','Total Emails'=>'Łączna liczba e-maili','Last week'=>'Ubiegły tydzień','Reports'=>'Raporty','Want More Stats?'=>'Czy chcesz uzyskać więcej statystyk?','Upgrade to <b>WP Mail SMTP Pro</b> and unlock <u>Email Log</u> and advanced <u>Email Reports</u>. Start measuring the success of your emails today!'=>'Kup <b>WP Mail SMTP Pro</b> i uzyskaj dostęp do <u>dziennika e-maili</u> oraz zaawansowanych <u>raportów o e-mailach</u>. Zacznij mierzyć skuteczność swoich e-maili już dziś.','WP Core'=>'Rdzeń WP','Unlock these awesome logging features:'=>'Uzyskaj dostęp do tych fantastycznych funkcji rejestrowania:','Save detailed email headers'=>'Zapisuj szczegółowe nagłówki e-maili','See sent and failed emails'=>'Przeglądaj wysłane i nieudane e-maile','Resend emails and attachments'=>'Ponownie wysyłaj e-maile i załączniki','Track email opens and clicks'=>'Śledź otwarcia i kliknięcia e-maili','Print email logs or save as PDF'=>'Drukuj dzienniki e-maili lub zapisuj je w formacie PDF','Disable Email Summaries'=>'Wyłącz podsumowania e-maili','Disable Email Summaries weekly delivery.'=>'Wyłącz cotygodniowe dostarczanie podsumowań e-maili.','Please enable <a href="%s">Email Logging</a> first, before this setting can be configured.'=>'Aby umożliwić skonfigurowanie tego ustawienia, najpierw włącz <a href="%s">rejestrowanie e-maili</a>.','View Email Summary Example'=>'Zobacz przykład podsumowania e-maili','Send Another Test Email'=>'Wyślij kolejny e-mail testowy','An email request was sent.'=>'Wysłano żądanie obsługi e-maila.','There was an error while upgrading the %1$s database. Please contact %2$s support with this information: %3$s.'=>'Podczas ulepszania bazy danych %1$s wystąpił błąd. Skontaktuj się z zespołem pomocy technicznej %2$s, podając następujące informacje: %3$s.','An email request was sent to the Gmail API.'=>'Wysłano żądanie obsługi e-maila do interfejsu Gmail API.','An error occurred when trying to get Gmail aliases: %s'=>'Wystąpił błąd podczas próby uzyskania aliasów Gmail: %s','There was an error while processing Google authorization: missing code or scope parameter.'=>'Wystąpił błąd podczas przetwarzania autoryzacji Google: brakujący kod lub zakres.','There was an error while processing Google authorization: %s'=>'Wystąpił błąd podczas przetwarzania autoryzacji Google: %s','Email Log Index'=>'Indeks dziennika e-maili','Individual Email Log'=>'Indywidualny dziennik e-maili','Unlock these awesome reporting features:'=>'Uzyskaj dostęp do tych fantastycznych funkcji raportowania:','Get weekly deliverability reports'=>'Otrzymuj tygodniowe raporty o dostarczaniu e-maili','View stats grouped by subject line'=>'Przeglądaj statystyki pogrupowane według tematu','Track total emails sent each week'=>'Śledź łączną liczbę e-maili wysłanych w każdym tygodniu','Measure open rate and click through rates'=>'Mierz współczynniki otwarcia i kliknięcia','Spot failed emails quickly'=>'Szybko wykrywaj nieudane e-maile','See email report graphs in WordPress'=>'Oglądaj wykresy raportów o e-mailach w WordPressie','Check this if you would like to debug the email sending process. Once enabled, all debug events will be logged in the table below. This setting should only be enabled for shorter debugging periods and disabled afterwards.'=>'Zaznacz tę opcję, jeśli chcesz debugować proces wysyłania e-maili. Po włączeniu tej opcji wszystkie zdarzenia debugowania będą rejestrowane w poniższej tabeli. To ustawienie należy włączać jedynie na krótkie okresy debugowania, a następnie wyłączać.','Search Events'=>'Wyszukaj zdarzenia','where event contains "%s"'=>'gdzie zdarzenie zawiera „%s”','on %s'=>'w dniu %s','between %1$s and %2$s'=>'między %1$s i %2$s','Debug Events are Not Installed Correctly'=>'Zdarzenia debugowania nie zostały poprawnie zainstalowane','For some reason the database table was not installed correctly. Please contact plugin support team to diagnose and fix the issue.'=>'Z jakiegoś powodu tabela bazy danych nie została zainstalowana poprawnie. Skontaktuj się z zespołem pomocy technicznej wtyczki, aby zdiagnozować i rozwiązać problem.','Email Reports'=>'Raporty o e-mailach','Stats at a Glance'=>'Statystyki w skrócie','Detailed Stats by Subject Line'=>'Szczegółowe statystyki według tematu','Weekly Email Report'=>'Tygodniowy raport o e-mailach','Found <strong>%1$s %2$s event</strong>'=>'Znaleziono <strong>%1$s zdarzenie typu %2$s</strong>' . "\0" . 'Znaleziono <strong>%1$s zdarzenia typu %2$s</strong>' . "\0" . 'Znaleziono <strong>%1$s zdarzeń typu %2$s</strong>','Weekly Email Summary'=>'Cotygodniowe podsumowanie e-maili','Get statistics about emails you\'ve sent.'=>'Otrzymuj statystyki dotyczące wysłanych e-maili.','Transparency and Disclosure'=>'Przejrzystość i jawność informacji','We believe in full transparency. The SMTP.com links above are tracking links as part of our partnership with SMTP (j2 Global). We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Wierzymy w pełną przejrzystość. Powyższe odnośniki do usługi SMTP.com to odnośniki śledzące, które stanowią element naszej współpracy z SMTP (j2 Global). Moglibyśmy polecić niemal każdą usługę SMTP, ale polecamy tylko produkty, które naszym zdaniem zapewnią wartość dodaną naszym użytkownikom.','We believe in full transparency. The Sendinblue links above are tracking links as part of our partnership with Sendinblue. We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Wierzymy w pełną przejrzystość. Powyższe odnośniki do usługi Sendinblue to odnośniki śledzące, które stanowią element naszej współpracy z Sendinblue. Moglibyśmy polecić niemal każdą usługę SMTP, ale polecamy tylko produkty, które naszym zdaniem zapewnią wartość dodaną naszym użytkownikom.','Enhanced Weekly Email Summary'=>'Ulepszone cotygodniowe podsumowanie e-maili','Read how to set up Microsoft Outlook / 365'=>'Poznaj sposób konfiguracji programu Microsoft Outlook / 365','<b>NEW!</b> Enable Weekly Email Summaries'=>'<b>NOWOŚĆ!</b> Włącz cotygodniowe podsumowania e-maili','View Example'=>'Zobacz przykład','Weekly Email Summaries have been enabled'=>'Cotygodniowe podsumowania e-maili zostały włączone','Access rejected.'=>'Odmowa dostępu.','You don\'t have the capability to perform this action.'=>'Nie masz możliwości wykonania tego działania.','All debug event entries were deleted successfully.'=>'Wszystkie wpisy zdarzeń debugowania zostały usunięte.','There was an issue while trying to delete all debug event entries. Error message: %s'=>'Podczas próby usunięcia wszystkich wpisów zdarzeń debugowania wystąpił problem. Komunikat o błędzie: %s','No Debug Event ID provided!'=>'Nie podano identyfikatora zdarzenia debugowania!','Number of events per page:'=>'Liczba zdarzeń na stronę:','Event #%d'=>'Zdarzenie nr %d','N/A'=>'Nd.','Debug Event Details'=>'Szczegóły zdarzenia debugowania','Date'=>'Data','Content'=>'Treść','%1$s (line: %2$s)'=>'%1$s (wiersz: %2$s)','Email Source: %s'=>'Źródło e-mail: %s','All'=>'Wszystko','Event'=>'Wydarzenie','No events found.'=>'Nie znaleziono zdarzeń.','No events have been logged for now.'=>'Obecnie nie ma zarejestrowanych zdarzeń.','Filter'=>'Filtruj','Delete All Events'=>'Usuń wszystkie zdarzenia','See Quick Links'=>'Zobacz szybkie odnośniki','Support & Docs'=>'Pomoc techniczna i dokumenty','Follow on Facebook'=>'Obserwuj na Facebooku','Suggest a Feature'=>'Zaproponuj funkcję','Debug Events'=>'Zdarzenia debugowania','Are you sure you want to permanently delete all debug events?'=>'Czy na pewno chcesz trwale usunąć wszystkie zdarzenia debugowania?','Close'=>'Zamknij','An error occurred!'=>'Wystąpił błąd!','On this page, you can view and configure different plugin debugging events. View email sending errors and enable debugging events, allowing you to detect email sending issues.'=>'Na tej stronie można przejrzeć i skonfigurować różne zdarzenia debugowania wtyczki. Sprawdź błędy wysyłania e-maili i włącz zdarzenia debugowania, aby wykrywać problemy z wysyłaniem wiadomości.','Event Types'=>'Rodzaje zdarzeń','Email Sending Errors'=>'Błędy wysyłania e-maili','This debug event is always enabled and will record any email sending errors in the table below.'=>'To zdarzenie debugowania jest zawsze włączone i powoduje rejestrowanie wszelkich błędów wysyłania e-maili w poniższej tabeli.','Debug Email Sending'=>'Debuguj wysyłanie e-maili','Select a date range'=>'Wybierz zakres dat','Export Type'=>'Rodzaj eksportu','Export in CSV (.csv)'=>'Eksport w formacie CSV (.csv)','Export in Microsoft Excel (.xlsx)'=>'Eksport w formacie Microsoft Excel (.xlsx)','Export in EML (.eml)'=>'Eksport w formacie EML (.eml)','Common Information'=>'Typowe informacje','To Address'=>'Adres odbiorcy','From Address'=>'Adres nadawcy','Subject'=>'Temat','Body'=>'Treść','Created Date'=>'Data utworzenia','Number of Attachments'=>'Liczba załączników','Attachments'=>'Załączniki','Additional Information'=>'Informacje dodatkowe','Carbon Copy (CC)'=>'Kopia do wiadomości (DW)','Blind Carbon Copy (BCC)'=>'Ukryta kopia do wiadomości (UDW)','Headers'=>'Nagłówki','Error Details'=>'Szczegóły błędu','Email log ID'=>'Identyfikator dziennika e-maili','Custom Date Range'=>'Własny zakres dat','Search'=>'Wyszukaj','Email Addresses'=>'Adresy e-mail','Hide Dashboard Widget'=>'Ukryj widżet kokpitu','Or disable the Sendinblue email sending setting in WooCommerce > Settings > Sendinblue (tab) > Email Options (tab) > Enable Sendinblue to send WooCommerce emails.'=>'Możesz też wyłączyć ustawienie wysyłania e-maili usługi Sendinblue w sekcji WooCommerce > Ustawienia > (karta) Sendinblue > (karta) Opcje poczty e-mail > Włącz Sendinblue w celu wysyłania e-maili WooCommerce.','WP Mail SMTP is using the <a href="%s" target="_blank" rel="noopener noreferrer">Action Scheduler</a> library, which allows it to queue and process bigger tasks in the background without making your site slower for your visitors. Below you can see the list of all tasks and their status. This table can be very useful when debugging certain issues.'=>'Wtyczka WP Mail SMTP korzysta z biblioteki <a href="%s" target="_blank" rel="noopener noreferrer">Action Scheduler</a>, która umożliwia kolejkowanie i przetwarzanie większych zadań w tle bez spowalniania witryny z perspektywy gości. Poniżej znajduje się lista wszystkich zadań i ich stanów. Tabela ta może się bardzo przydać podczas rozwiązywania niektórych problemów.','Action Scheduler library is also used by other plugins, like WPForms and WooCommerce, so you might see tasks that are not related to our plugin in the table below.'=>'Z biblioteki Action Scheduler korzystają także inne wtyczki, takie jak WPForms i WooCommerce, więc w poniższej tabeli mogą się znajdować zadania niezwiązane z naszą wtyczką.','Search results for <strong>%s</strong>'=>'Wyniki wyszukiwania terminu <strong>%s</strong>','Export'=>'Eksport','Export Email Logs'=>'Eksportowanie dzienników e-maili','There was an error while processing the authentication request. Please recheck your Region, Client ID and Client Secret and try again.'=>'Podczas przetwarzania żądania uwierzytelnienia wystąpił błąd. Sprawdź ponownie region, identyfikator klienta oraz klucz prywatny klienta i spróbuj ponownie.','View Detailed Email Stats'=>'Przeglądaj szczegółowe statystyki e-maili','Automatically keep track of every email sent from your WordPress site and view valuable statistics right here in your dashboard.'=>'Automatycznie śledź każdy e-mail wysłany z twojej witryny w WordPressie i przeglądaj cenne statystyki bezpośrednio w kokpicie.','<a href="%s" target="_blank" rel="noopener noreferrer">Upgrade to Pro</a> for detailed stats, email logs, and more!'=>'<a href="%s" target="_blank" rel="noopener noreferrer">Kup Pro</a>, aby uzyskać dostęp do szczegółowych statystyk, dzienników e-maili i nie tylko!','Select timespan'=>'Wybierz przedział czasu','All Time'=>'Wszystko','Confirmed Emails'=>'Potwierdzone e-maile','Unconfirmed Emails'=>'Niepotwierdzone e-maile','Failed Emails'=>'Nieudane e-maile','Sent Emails'=>'Wysłane e-maile','Select email type'=>'Wybierz rodzaj e-maili','All Emails'=>'Wszystkie e-maile','Graph Style'=>'Styl wykresu','Bar'=>'Słupkowy','Line'=>'Liniowy','Color Scheme'=>'Schemat kolorów','WordPress'=>'WordPress','Table cell icon'=>'Ikonka komórki tabeli','%d total'=>'%d ogółem','Confirmed %s'=>'Potwierdzone %s','Unconfirmed %s'=>'Niepotwierdzone %s','Failed %s'=>'Nieudane %s','Sent %s'=>'Wysłane %s','Notifications'=>'Powiadomienia','Scheduled Actions'=>'Zaplanowane działania','Last %d day'=>'Ostatni %d dzień' . "\0" . 'Ostatnie %d dni' . "\0" . 'Ostatnie %d dni','Tools'=>'Narzędzia','Is email domain configured properly?'=>'Czy domena e-mail jest prawidłowo skonfigurowana?','Current from email domain'=>'Obecna domena e-mail nadawcy','Email domain is configured correctly'=>'Domena e-mail została skonfigurowana poprawnie','All checks for your email domain were successful. It looks like everything is configured correctly.'=>'Wszystkie operacje sprawdzania domeny e-mail przebiegły pomyślnie. Wygląda na to, że wszystko zostało poprawnie skonfigurowane.','Email domain issues detected'=>'Wykryto problemy z domeną e-mail','Unable to create directory %s. Is its parent directory writable by the server?'=>'Nie można utworzyć katalogu %s. Czy serwer ma uprawnienia do zapisu w przypadku katalogu nadrzędnego?','Unable to write in WPMailSMTP upload directory %s. Is it writable by the server?'=>'Nie można zapisać w katalogu przesyłania wtyczki WP Mail SMTP: %s. Czy serwer ma uprawnienia do zapisu w jego przypadku?','You can also send emails with different From Email addresses, by disabling the Force From Email setting and using registered aliases throughout your WordPress site as the From Email addresses.'=>'Możesz też wysyłać e-maile przy użyciu różnych adresów e-mail nadawcy. W tym celu wyłącz ustawienie Wymuś adres e-mail nadawcy i używaj zarejestrowanych aliasów w całej witrynie WordPressa jako adresów e-mail nadawcy.','Easily display Instagram content on your WordPress site without writing any code. Comes with multiple templates, ability to show content from multiple accounts, hashtags, and more. Trusted by 1 million websites.'=>'Łatwo wyświetlaj treści z Instagrama w swojej witrynie w WordPressie, nie pisząc żadnego kodu. Zawiera wiele szablonów, możliwość wyświetlania treści z wielu kont, hashtagi i inne funkcje. Narzędzie używane w ponad milionie witryn.','Smash Balloon Facebook Feeds'=>'Smash Balloon Facebook Feeds','Easily display Facebook content on your WordPress site without writing any code. Comes with multiple templates, ability to embed albums, group content, reviews, live videos, comments, and reactions.'=>'Łatwo wyświetlaj treści z Facebooka w swojej witrynie w WordPressie, nie pisząc żadnego kodu. Zawiera wiele szablonów, możliwość osadzania albumów, obsługę treści z grup, oceny, filmy na żywo, komentarze i reakcje.','Smash Balloon YouTube Feeds'=>'Smash Balloon YouTube Feeds','Easily display YouTube videos on your WordPress site without writing any code. Comes with multiple layouts, ability to embed live streams, video filtering, ability to combine multiple channel videos, and more.'=>'Łatwo wyświetlaj filmy z YouTube w swojej witrynie w WordPressie, nie pisząc żadnego kodu. Zawiera wiele układów, możliwość osadzania transmisji strumieniowych na żywo, filtrowanie filmów, możliwość łączenia filmów z różnych kanałów i inne funkcje.','Smash Balloon Twitter Feeds'=>'Smash Balloon Twitter Feeds','Easily display Twitter content in WordPress without writing any code. Comes with multiple layouts, ability to combine multiple Twitter feeds, Twitter card support, tweet moderation, and more.'=>'Łatwo wyświetlaj treści z Twittera w swojej witrynie w WordPressie, nie pisząc żadnego kodu. Zawiera wiele układów, możliwość łączenia różnych kanałów Twittera, obsługę kart Twittera, moderację tweetów i inne funkcje.','TrustPulse'=>'TrustPulse','Boost your sales and conversions by up to 15% with real-time social proof notifications. TrustPulse helps you show live user activity and purchases to help convince other users to purchase.'=>'Zwiększ sprzedaż i konwersje nawet o 15% dzięki przesyłanym w czasie rzeczywistym powiadomieniom opartym na teorii społecznego dowodu słuszności. TrustPulse pomaga na bieżąco wyświetlać aktywność użytkowników i dokonywane przez nich zakupy, aby przekonać do zakupu kolejne osoby.','Launch Setup Wizard'=>'Uruchom kreator konfiguracji','We\'ll guide you through each step needed to get WP Mail SMTP fully set up on your site.'=>'Przeprowadzimy cię przez każdy z kroków potrzebnych do pełnego skonfigurowania wtyczki WP Mail SMTP w twojej witrynie.','The original WordPress SEO plugin and toolkit that improves your website’s search rankings. Comes with all the SEO features like Local SEO, WooCommerce SEO, sitemaps, SEO optimizer, schema, and more.'=>'Oryginalna wtyczka i zestaw narzędzi SEO do WordPressa, które poprawiają pozycję witryny w wynikach wyszukiwania. Zawiera wszystkie potrzebne funkcje pozycjonowania, takie jak SEO lokalne, SEO dla WooCommerce, mapy witryn, optymalizator SEO, schemat itd.','SeedProd'=>'SeedProd','The fastest drag & drop landing page builder for WordPress. Create custom landing pages without writing code, connect them with your CRM, collect subscribers, and grow your audience. Trusted by 1 million sites.'=>'Najszybszy kreator stron docelowych do WordPressa oparty na technice przeciągania elementów. Twórz własne strony docelowe bez pisania kodu, łącz je ze swoim systemem CRM, zdobywaj subskrybentów i powiększaj grono odbiorców. Narzędzie używane w milionie witryn.','Turn your website visitors into brand ambassadors! Easily grow your email list, website traffic, and social media followers with the most powerful giveaways & contests plugin for WordPress.'=>'Zmień osoby odwiedzające twoją witrynę internetową w ambasadorów marki! Łatwo powiększaj listę adresów e-mail, ruch w witrynie oraz grono obserwujących w mediach społecznościowych przy użyciu najwydajniejszej wtyczki losowań i konkursów do WordPressa.','PushEngage'=>'PushEngage','Connect with your visitors after they leave your website with the leading web push notification software. Over 10,000+ businesses worldwide use PushEngage to send 15 billion notifications each month.'=>'Kontaktuj się z gośćmi, którzy opuścili twoją witrynę, korzystając z czołowej wtyczki do internetowych powiadomień push. Ponad 10 000 firm na całym świecie korzysta z PushEngage, wysyłając każdego miesiąca 15 miliardów powiadomień.','Smash Balloon Instagram Feeds'=>'Smash Balloon Instagram Feeds','Instantly get more subscribers, leads, and sales with the #1 conversion optimization toolkit. Create high converting popups, announcement bars, spin a wheel, and more with smart targeting and personalization.'=>'Najlepszy zestaw narzędzi do optymalizacji konwersji, dzięki któremu możesz błyskawicznie zwiększyć liczbę subskrybentów i potencjalnych klientów oraz wielkość sprzedaży. Twórz skuteczne okna pop-up, paski ogłoszeń, „koła fortuny” oraz inne elementy z inteligentnymi funkcjami targetowania i personalizacji.','The best drag & drop WordPress form builder. Easily create beautiful contact forms, surveys, payment forms, and more with our 600+ form templates. Trusted by over 5 million websites as the best forms plugin.'=>'Najlepszy kreator formularzy kontaktowych do WordPressa oparty na technice przeciągania elementów. Łatwo twórz piękne formularze kontaktowe, ankiety, formularze płatności i nie tylko przy użyciu ponad 600 szablonów. Najlepsza wtyczka formularzy, której zaufali właściciele ponad 5 milionów witryn internetowych.','The leading WordPress analytics plugin that shows you how people find and use your website, so you can make data driven decisions to grow your business. Properly set up Google Analytics without writing code.'=>'Czołowa wtyczka analityczna do WordPressa, która pokazuje, jak goście znajdują twoją witrynę i jak z niej korzystają, dzięki czemu możesz podejmować oparte na danych decyzje dotyczące rozwijania działalności. Teraz możesz prawidłowo skonfigurować usługę Google Analytics bez pisania kodu.','AIOSEO'=>'AIOSEO','You have successfully linked the current site with your Microsoft API project. Now you can start sending emails through Outlook.'=>'Udało się połączyć obecną witrynę z projektem Microsoft API. Teraz możesz rozpocząć wysyłanie e-maili za pośrednictwem programu Outlook.','Error Message:'=>'Komunikat o błędzie:','Please fill out all the required fields to continue.'=>'Uzupełnij wszystkie wymagane pola, aby kontynuować.','Return to Plugin Settings'=>'Wróć do ustawień wtyczki','%1$s, %2$s'=>'%1$s, %2$s','It looks like we can\'t save the settings.'=>'Wygląda na to, że nie można zapisać ustawień.','Network error encountered. Settings not saved.'=>'Napotkano błąd sieci. Ustawienia nie zostały zapisane.','It looks like we can\'t import the plugin settings.'=>'Wygląda na to, że nie można zaimportować ustawień wtyczki.','Network error encountered. SMTP plugin import failed!'=>'Napotkano błąd sieci. Importowanie wtyczki SMTP nie powiodło się!','It looks like we can\'t load authentication details.'=>'Wygląda na to, że nie można wczytać danych uwierzytelniających.','It looks like we can\'t load the settings.'=>'Wygląda na to, że nie można wczytać ustawień.','It looks like we can\'t retrieve Amazon SES Identities.'=>'Wygląda na to, że nie można pobrać tożsamości Amazon SES.','Can\'t retrieve Amazon SES Identities.'=>'Nie można pobrać tożsamości Amazon SES.','Can\'t register the Amazon SES Identity'=>'Nie można zarejestrować tożsamości Amazon SES','Which email features do you want to enable?'=>'Które funkcje e-mail chcesz włączyć?','Make sure you\'re getting the most out of WP Mail SMTP. Just check all of the features you\'d like to use, and we\'ll go ahead and enable those for you.'=>'Zadbaj o pełne wykorzystanie możliwości wtyczki WP Mail SMTP. Po prostu zaznacz wszystkie funkcje, których chcesz używać, a my je dla ciebie włączymy.','The following plugin will be installed for free: WPForms'=>'Poniższa wtyczka zostanie zainstalowana bezpłatnie: WPForms','Improved Email Deliverability'=>'Skuteczniejsze dostarczanie e-maili','Ensure your emails are sent successfully and reliably.'=>'Zadbaj o pomyślne i niezawodne dostarczanie e-maili.','Email Error Tracking'=>'Śledzenie błędów e-maili','Easily spot errors causing delivery issues.'=>'Łatwo wykrywaj błędy powodujące problemy z dostarczaniem.','Smart Contact Form'=>'Inteligentny formularz kontaktowy','Create beautiful contact forms with just a few clicks.'=>'Twórz piękne formularze kontaktowe za pomocą kilku kliknięć.','Detailed Email Logs'=>'Szczegółowe dzienniki e-maili','Keep records of every email that\'s sent out from your website.'=>'Rejestruj każdy e-mail wysłany z twojej witryny.','Manage Default Notifications'=>'Zarządzaj domyślnymi powiadomieniami','Control which email notifications your WordPress site sends.'=>'Kontroluj powiadomienia e-mail wysyłane z twojej witryny w WordPressie.','Multisite Network Settings'=>'Ustawienia sieci wielu witryn','Save time with powerful WordPress Multisite controls.'=>'Oszczędzaj czas dzięki zaawansowanym mechanizmom sterowania wieloma witrynami WordPressa.','Please input the sending domain/subdomain you configured in your SendGrid dashboard. More information can be found in our %1$sSendGrid documentation%2$s'=>'Wpisz domenę/poddomenę wysyłającą, która została skonfigurowana w kokpicie SendGrid. Więcej informacji można znaleźć w naszej %1$sdokumentacji usługi SendGrid%2$s','Configure Mailer Settings'=>'Skonfiguruj ustawienia usługi pocztowej','Below, we\'ll show you all of the settings required to set up this mailer.'=>'Poniżej przedstawimy wszystkie ustawienia wymagane do skonfigurowania tej usługi pocztowej.','We\'re running some tests in the background to make sure everything is set up properly.'=>'Wykonujemy testy w tle, aby mieć pewność, że wszystkie ustawienia są poprawnie skonfigurowane.','Checking mailer configuration image'=>'Obrazek sprawdzania konfiguracji usługi pocztowej','Help Improve WP Mail SMTP + Smart Recommendations'=>'Pomoc w ulepszaniu wtyczki WP Mail SMTP + inteligentne zalecenia','Get helpful suggestions from WP Mail SMTP on how to optimize your email deliverability and grow your business.'=>'Otrzymuj od wtyczki WP Mail SMTP przydatne sugestie, które pomogą ci zoptymalizować dostarczanie e-mail i rozwijać działalność.','Your Email Address'=>'Twój adres e-mail','Your email is needed, so you can receive recommendations.'=>'Do otrzymywania zaleceń potrzebny jest twój adres e-mail.','Help make WP Mail SMTP better for everyone'=>'Pomóż nam ulepszać wtyczkę WP Mail SMTP','Yes, count me in'=>'Tak, chętnie','How was your WP Mail SMTP setup experience?'=>'Jak ci się podobała procedura konfiguracji wtyczki WP Mail SMTP?','Our goal is to make your SMTP setup as simple and straightforward as possible. We\'d love to know how this process went for you!'=>'Chcemy, by procedura konfiguracji SMTP była maksymalnie prosta. Chętnie się dowiemy, jak cały ten proces przebiegł w twoim przypadku!','Congrats, you’ve successfully set up WP Mail SMTP!'=>'Gratulacje, pomyślnie skonfigurowano wtyczkę WP Mail SMTP!','Here’s what to do next:'=>'Oto co możesz zrobić w następnej kolejności:','Check out our other free WordPress plugins:'=>'Sprawdź nasze inne bezpłatne wtyczki do WordPressa:','Upgrade to Unlock Powerful SMTP Features'=>'Ulepsz plan, aby uzyskać dostęp do zaawansowanych funkcji SMTP','Upgrade to Pro Today'=>'Kup Pro już dziś','%1$sBonus:%2$s You can upgrade to the Pro plan and %3$ssave %5$s today%4$s, automatically applied at checkout.'=>'%1$sBonus:%2$s możesz kupić plan Pro i %3$sjuż dziś uzyskać %5$s zniżki%4$s, która zostanie automatycznie zastosowana na etapie płatności.','Star icon'=>'Ikonka gwiazdy','Thanks for the feedback!'=>'Dziękujemy za uwagi!','Help us spread the word %1$sby giving WP Mail SMTP a 5-star rating %3$s(%4$s) on WordPress.org%2$s. Thanks for your support and we look forward to bringing you more awesome features.'=>'Przyczyń się do popularyzacji wtyczki WP Mail SMTP, %1$swystawiając jej 5-gwiazdkową ocenę%3$s(%4$s) na stronie WordPress.org%2$s. Dziękujemy za wsparcie i obiecujemy kolejne fantastyczne funkcje.','Rate on WordPress.org'=>'Ocena na WordPress.org','What could we do to improve?'=>'Co moglibyśmy poprawić?','We\'re sorry things didn\'t go smoothly for you, and want to keep improving. Please let us know any specific parts of this process that you think could be better. We really appreciate any details you\'re willing to share!'=>'Przykro nam, że nie wszystko poszło gładko – zależy nam na ciągłym doskonaleniu. Wskaż etapy procesu, które twoim zdaniem można by ulepszyć. Będziemy wdzięczni za wszelkie informacje, które zechcesz przekazać!','Yes, I give WP Mail SMTP permission to contact me for any follow up questions.'=>'Tak, pozwalam zespołowi WP Mail SMTP na kontaktowanie się ze mną w sprawie ewentualnych pytań dodatkowych.','Submit Feedback'=>'Prześlij informację zwrotną','Please input the sending domain/subdomain you configured in your Sendinblue dashboard. More information can be found in our %1$sSendinblue documentation%2$s'=>'Wpisz domenę/poddomenę wysyłającą, która została skonfigurowana w kokpicie Sendinblue. Więcej informacji można znaleźć w naszej %1$sdokumentacji usługi Sendinblue%2$s','Enable Auto TLS'=>'Włącz funkcję Auto TLS','Which mailer would you like to use to send emails? Not sure which mailer to choose? Check out our %1$scomplete mailer guide%2$s for details on each option.'=>'Jakiej usługi pocztowej chcesz używać do wysyłania e-maili? Nie wiesz, którą usługę wybrać? Zapoznaj się z naszym %1$skompleksowym przewodnikiem po usługach pocztowych%2$s, aby uzyskać szczegółowe informacje na temat każdej opcji.','Successful Upgrade!'=>'Ulepszenie zakończone powodzeniem!','Upgrade Failed!'=>'Ulepszenie nie powiodło się!','Enter your WP Mail SMTP License Key'=>'Wpisz klucz licencyjny wtyczki WP Mail SMTP','You\'re currently using %1$sWP Mail SMTP Lite%2$s - no license needed. Enjoy!'=>'Obecnie używasz wtyczki %1$sWP Mail SMTP Lite%2$s – licencja nie jest potrzebna. Miłego korzystania!','Continue'=>'Kontynuuj','Would you like to purchase the following features now?'=>'Czy chcesz teraz kupić poniższe funkcje?','These features are available as part of WP Mail SMTP Pro plan.'=>'Te funkcje są dostępne w planie WP Mail SMTP Pro.','Purchase Now'=>'Kup teraz','I\'ll do it later'=>'Zrobię to później','To unlock selected features, %1$sUpgrade to Pro%2$s and enter your license key below.'=>'Aby uzyskać dostęp do wybranych funkcji, %1$skup Pro%2$s i wpisz klucz licencyjny poniżej.','Already purchased? Enter your license key below to connect with %1$sWP Mail SMTP Pro%2$s!'=>'Już masz kupiony ten plan? Wpisz klucz licencyjny poniżej, aby nawiązać połączenie z wtyczką %1$sWP Mail SMTP Pro%2$s!','Enter your license key below to unlock plugin updates!'=>'Wpisz poniżej klucz licencyjny, aby uzyskać dostęp do aktualizacji wtyczki!','Verify License Key'=>'Zweryfikuj klucz licencyjny','The License Key format is incorrect. Please enter a valid key and try again.'=>'Format klucza licencyjnego jest nieprawidłowy. Wpisz prawidłowy klucz i spróbuj ponownie.','Your license was successfully verified! You are ready for the next step.'=>'Twoja licencja została pomyślnie zweryfikowana! Możesz przejść do następnego kroku.','Pro badge'=>'Odznaka Pro','License key input'=>'Wpisywanie klucza licencyjnego','Paste your license key here'=>'Wklej tutaj klucz licencyjny','Successful Verification!'=>'Weryfikacja przebiegła pomyślnie!','Verification Error!'=>'Błąd weryfikacji!','Please enter a value between %1$s and %2$s'=>'Wpisz wartość z przedziału od %1$s do %2$s.','Value has to be a round number'=>'Wartość musi być liczbą zaokrągloną','Successful Authorization'=>'Autoryzacja przebiegła pomyślnie','Authorization Error!'=>'Błąd autoryzacji!','Before continuing, you\'ll need to allow this plugin to send emails using your %s account.'=>'Zanim przejdziesz dalej, musisz zezwolić tej wtyczce na wysyłanie e-maili przy użyciu twojego konta %s .','Installed'=>'Zainstalowano','Upgrade to WP Mail SMTP Pro to unlock more awesome features and experience why WP Mail SMTP is used by over 4,000,000 websites.'=>'Kup wtyczkę WP Mail SMTP Pro, aby uzyskać dostęp do większej liczby fantastycznych funkcji i przekonać się, dlaczego wtyczka WP Mail SMTP jest używana w ponad 4 000 000 witryn internetowych.','Settings Updated'=>'Zaktualizowano ustawienia','Could Not Save Changes'=>'Nie udało się zapisać zmian','Return to Mailer Settings'=>'Wróć do ustawień usługi pocztowej','Whoops, we found an issue!'=>'Ups, wystąpił problem!','It looks like something went wrong...'=>'Wygląda na to, że coś poszło nie tak...','WP Mail SMTP has detected that your site is running an outdated, insecure version of PHP (%1$s). Some mailers require at least PHP version 5.6. Updating to the recommended version (PHP %2$s) only takes a few minutes and will make your website significantly faster and more secure.'=>'Wtyczka WP Mail SMTP wykryła, że twoja witryna korzysta z przestarzałej, niezabezpieczonej wersji języka PHP (%1$s). Niektóre usługi pocztowe wymagają języka PHP w wersji co najmniej 5.6. Aktualizacja do zalecanej wersji (PHP %2$s) zajmie tylko kilka minut i sprawi, że witryna będzie znacznie szybsza i lepiej zabezpieczona.','Yikes! WordPress Update Required'=>'O rany! Wymagana aktualizacja WordPressa','WP Mail SMTP has detected that your site is running an outdated version of WordPress (%s). WP Mail SMTP requires at least WordPress version 4.9.'=>'Wtyczka WP Mail SMTP wykryła, że twoja witryna korzysta z przestarzałej wersji WordPressa (%s). WP Mail SMTP wymaga WordPressa w wersji co najmniej 4.9.','It looks like we can\'t load oAuth redirect.'=>'Wygląda na to, że nie można wczytać przekierowania oAuth.','It looks like we can\'t load existing settings.'=>'Wygląda na to, że nie można wczytać istniejących ustawień.','It looks like we can\'t load oAuth connected data.'=>'Wygląda na to, że nie można wczytać połączonych danych oAuth.','It looks like we can\'t remove oAuth connection.'=>'Wygląda na to, że nie można usunąć połączenia oAuth.','It looks like we can\'t retrieve the Amazon SES Identities.'=>'Wygląda na to, że nie można pobrać tożsamości Amazon SES.','It looks like we can\'t register the Amazon SES Identity.'=>'Wygląda na to, że nie można zarejestrować tożsamości Amazon SES.','It looks like we can\'t perform the mailer configuration check.'=>'Wygląda na to, że nie można sprawdzić konfiguracji usługi pocztowej.','It looks like we can\'t send the feedback.'=>'Wygląda na to, że nie można wysłać uwag.','You appear to be offline.'=>'Wygląda na to, że jesteś offline.','It looks like the plugin installation failed!'=>'Wygląda na to, że instalacja wtyczki nie powiodła się!','It looks like we can\'t install the plugin.'=>'Wygląda na to, że nie można zainstalować wtyczki.','You appear to be offline. Plugin not installed.'=>'Wygląda na to, że jesteś offline. Wtyczka nie została zainstalowana.','Can\'t fetch plugins information.'=>'Nie można pobrać informacji o wtyczkach.','It looks like we can\'t fetch plugins information.'=>'Wygląda na to, że nie można pobrać informacji o wtyczkach.','You appear to be offline. Plugin information not retrieved.'=>'Wygląda na to, że jesteś offline. Informacje o wtyczce nie zostały pobrane.','Welcome to the WP Mail SMTP Setup Wizard!'=>'Witamy w kreatorze konfiguracji wtyczki WP Mail SMTP!','We’ll guide you through each step needed to get WP Mail SMTP fully set up on your site.'=>'Przeprowadzimy cię przez każdy z kroków potrzebnych do pełnego skonfigurowania wtyczki WP Mail SMTP w twojej witrynie.','Let\'s Get Started'=>'Zaczynajmy','Save and Continue'=>'Zapisz i kontynuuj','Previous Step'=>'Poprzedni krok','%1$sFollow this link%2$s to get a Domain Name from Mailgun.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać nazwę domeny z usługi Mailgun.','Define which endpoint you want to use for sending messages. If you are operating under EU laws, you may be required to use EU region. %1$sMore information%2$s on Mailgun.com.'=>'Określ, którego punktu końcowego chcesz używać do wysyłania wiadomości. Jeśli podlegasz przepisom UE, może być wymagane użycie regionu UE. %1$sWięcej informacji%2$s na stronie Mailgun.com.','If enabled, the From Name setting above will be used for all emails, ignoring values set by other plugins.'=>'W przypadku włączenia tej opcji we wszystkich e-mailach będą używane ustawione wyżej imię i nazwisko nadawcy, a wartości ustawione przez inne wtyczki będą ignorowane.','If enabled, the From Email setting above will be used for all emails, ignoring values set by other plugins.'=>'W przypadku włączenia tej opcji we wszystkich e-mailach będzie używany ustawiony wyżej adres e-mail nadawcy, a wartości ustawione przez inne wtyczki będą ignorowane.','Read how to set up Mailgun'=>'Poznaj sposób konfiguracji usługi Mailgun','Close and exit the Setup Wizard'=>'Zamknij i wyjdź z Kreatora konfiguracji','%1$sFollow this link%2$s to get an API Key for Sendgrid.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać klucz API usługi Sendgrid.','To send emails you will need only a %1$sMail Send%2$s access level for this API key.'=>'Do wysyłania e-maili potrzebujesz tylko dostępu na poziomie %1$sMail Send%2$s (wysyłanie poczty) dla tego klucza API.','Read how to set up Sendgrid'=>'Poznaj sposób konfiguracji usługi Sendgrid','Step %1$s of %2$s'=>'Krok %1$s z %2$s','Copy input value'=>'Skopiuj wartość wejściową','Copied!'=>'Skopiowano!','The value entered does not match the required format'=>'Wpisana wartość jest niezgodna z wymaganym formatem','Checking Mailer Configuration'=>'Sprawdzanie konfiguracji usługi pocztowej','Whoops, looks like things aren’t configured properly.'=>'Ups, wygląda na to, że ustawienia nie są poprawnie skonfigurowane.','We just tried to send a test email, but something prevented that from working. To see more details about the issue we detected, as well as our suggestions to fix it, please start troubleshooting.'=>'Spróbowaliśmy wysłać e-mail testowy, ale z jakiegoś powodu to się nie udało. Aby zobaczyć więcej informacji na temat wykrytego problemu, a także sugerowane sposoby jego rozwiązania, rozpocznij rozwiązywanie problemów.','Start Troubleshooting'=>'Rozpocznij rozwiązywanie problemów','Send us Feedback'=>'Wyślij uwagi','Finish Setup'=>'Ukończ konfigurację','Import data from your current plugins'=>'Zaimportuj dane z obecnych wtyczek','We have detected other SMTP plugins installed on your website. Select which plugin\'s data you would like to import to WP Mail SMTP.'=>'Wykryliśmy, że w twojej witrynie są zainstalowane inne wtyczki SMTP. Wybierz wtyczkę, której dane chcesz zaimportować do wtyczki WP Mail SMTP.','Import Data and Continue'=>'Zaimportuj dane i kontynuuj','Skip this Step'=>'Pomiń ten krok','Easy WP SMTP'=>'Easy WP SMTP','SMTP Mailer'=>'SMTP Mailer','WP SMTP'=>'WP SMTP','The data center location used by your Zoho account.'=>'Lokalizacja centrum danych używana na twoim koncie Zoho.','Redirect URI'=>'URI przekierowania','Read how to set up Zoho Mail'=>'Poznaj sposób konfiguracji usługi Zoho Mail','%1$sFollow this link%2$s to get an API Key for SMTP.com.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać klucz API usługi SMTP.com.','%1$sFollow this link%2$s to get a Sender Name for SMTP.com.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać imię i nazwisko nadawcy z usługi SMTP.com.','Read how to set up SMTP.com'=>'Poznaj sposób konfiguracji usługi SMTP.com','%1$sFollow this link%2$s to get an API Key for Sendinblue.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać klucz API usługi Sendinblue.','Get Started with Sendinblue'=>'Rozpocznij korzystanie z usługi Sendinblue','Read how to set up Sendinblue'=>'Poznaj sposób konfiguracji usługi Sendinblue','Access Key ID'=>'Identyfikator klucza dostępu','Secret Access Key'=>'Prywatny klucz dostępu','SES Identities'=>'Tożsamości SES','Please select the Amazon SES API region which is the closest to where your website is hosted. This can help to decrease network latency between your site and Amazon SES, which will speed up email sending.'=>'Wybierz region API usługi Amazon SES znajdujący się najbliżej miejsca, w którym hostowana jest twoja witryna internetowa. Może to pomóc w zmniejszeniu opóźnienia sieciowego między twoją witryną i usługą Amazon SES, co przyspieszy wysyłanie e-maili.','Read how to set up Amazon SES'=>'Poznaj sposób konfiguracji usługi Amazon SES','Choose Your SMTP Mailer'=>'Wybierz usługę pocztową SMTP','I Understand, Continue'=>'Rozumiem, kontynuuj','Choose a Different Mailer'=>'Wybierz inną usługę pocztową','Recommended Mailers'=>'Zalecane usługi pocztowe','is a PRO Feature'=>'to funkcja PRO','Authorized Redirect URI'=>'Autoryzowany identyfikator URI przekierowania','Select which email address you would like to send your emails from.'=>'Wybierz adres e-mail, z którego chcesz wysyłać e-maile.','Read how to set up the Gmail mailer'=>'Poznaj sposób konfiguracji usługi pocztowej Gmail','Application ID'=>'Identyfikator aplikacji','Application Password'=>'Hasło aplikacji','There was an error while processing the authentication request. Please recheck your Client ID and Client Secret and try again.'=>'Podczas przetwarzania żądania uwierzytelnienia wystąpił błąd. Sprawdź ponownie identyfikator klienta oraz klucz prywatny klienta i spróbuj ponownie.','Connect to %s'=>'Połącz z: %s','If you want to use a different From Email address you can setup a Google email alias. %1$sFollow these instructions%2$s, then select the alias in the From Email section below.'=>'Jeśli chcesz użyć innego adresu e-mail nadawcy, możesz skonfigurować alias adresu e-mail Google. %1$sPostępuj zgodnie z tymi instrukcjami%2$s, a następnie wybierz alias w poniższej  sekcji Adres e-mail nadawcy.','Removing this OAuth connection will give you the ability to redo the OAuth connection or connect to different %s account.'=>'Usunięcie tego połączenia OAuth umożliwi ci ponowne utworzenie połączenia OAuth lub połączenie się z innym kontem %s.','Connected as'=>'Połączono jako','Please enter a domain'=>'Wpisz domenę','Please enter a valid email address'=>'Wpisz prawidłowy adres e-mail','Enter the domain name to verify it on Amazon SES and generate the required DNS CNAME records.'=>'Wpisz nazwę domeny, aby zweryfikować ją w usłudze Amazon SES i wygenerować wymagane rekordy DNS CNAME.','Enter a valid email address. A verification email will be sent to the email address you entered.'=>'Wpisz prawidłowy adres e-mail. Na wpisany adres zostanie wysłany e-mail weryfikacyjny.','Please check the inbox of <b>%s</b> for a confirmation email.'=>'Sprawdź skrzynkę odbiorczą adresu <b>%s</b>, w której powinien się znajdować e-mail z potwierdzeniem.','Verify Email'=>'Zweryfikuj adres e-mail','No registered domains or emails.'=>'Brak zarejestrowanych domen i adresów e-mail.','You will not be able to send emails until you verify at least one domain or email address for the selected Amazon SES Region.'=>'Wysyłanie e-maili nie będzie możliwe, dopóki nie zweryfikujesz co najmniej jednej domeny lub jednego adresu e-mail dla wybranego regionu Amazon SES.','View DNS'=>'Zobacz DNS','Resend'=>'Wyślij ponownie','Here are the domains and email addresses that have been verified and can be used as the From Email.'=>'Oto domeny i adresy e-mail, które zostały zweryfikowane i mogą być używane jako adres e-mail nadawcy.','Verify SES Identity'=>'Zweryfikuj tożsamość SES','Add New SES Identity'=>'Utwórz nową tożsamość SES','Name'=>'Nazwa','Value'=>'Wartość','Please add these CNAME records to your domain\'s DNS settings. For information on how to add CNAME DNS records, please refer to the %1$sAmazon SES documentation%2$s.'=>'Dodaj te rekordy CNAME do ustawień DNS swojej domeny. Aby uzyskać informacje na temat sposobu dodawania rekordów DNS CNAME, zapoznaj się z %1$sdokumentacją usługi Amazon SES%2$s.','Verify Domain'=>'Zweryfikuj domenę','Verify Email Address'=>'Zweryfikuj adres e-mail','Post SMTP Mailer'=>'Post SMTP Mailer','%1$sFollow this link%2$s to get an API Key for Brevo.'=>'%1$sKliknij ten odnośnik%2$s, aby uzyskać klucz API usługi Brevo.','WP Mail SMTP has detected that your site is running an outdated, insecure version of PHP (%1$s), which could be putting your site at risk for being hacked. WordPress stopped supporting your PHP version in April, 2019. Updating to the recommended version (PHP %2$s) only takes a few minutes and will make your website significantly faster and more secure.'=>'Wtyczka WP Mail SMTP wykryła, że twoja witryna korzysta z przestarzałej, niezabezpieczonej wersji języka PHP (%1$s), co może stwarzać ryzyko włamania do witryny. WordPress zakończył obsługiwanie tej wersji języka PHP w kwietniu 2019 r. Aktualizacja do zalecanej wersji (PHP %2$s) zajmie tylko kilka minut i sprawi, że witryna będzie znacznie szybsza i lepiej zabezpieczona.','Yikes! PHP Update Required'=>'O rany! Wymagana aktualizacja języka PHP','Go back to the Dashboard'=>'Wróć do kokpitu','WP Mail SMTP logo'=>'Logo WP Mail SMTP','Connect'=>'Połącz','Something went wrong. Please try again later.'=>'Coś poszło nie tak. Spróbuj ponownie później.','Domain Check Results'=>'Wyniki sprawdzania domeny','%s icon'=>'Ikonka %s','Setup Wizard'=>'Kreator konfiguracji','Already purchased? Simply enter your license key below to connect with WP Mail SMTP Pro!'=>'Już masz kupiony ten plan? Aby się połączyć z wtyczką WP Mail SMTP Pro, wpisz poniżej klucz licencyjny!','Paste license key here'=>'Wklej tutaj klucz licencyjny','Make sure your API Key in the SendGrid mailer settings is correct and valid.'=>'Upewnij się, że w ustawieniach usługi pocztowej SendGrid został skonfigurowany prawidłowy klucz API.','Save the plugin settings.'=>'Zapisz ustawienia wtyczki.','If updating the API Key doesn\'t resolve this issue, please contact our support.'=>'Jeśli zaktualizowanie klucza API nie rozwiąże problemu, skontaktuj się z naszym zespołem pomocy technicznej.','The test email might have sent, but its deliverability should be improved.'=>'E-mail testowy mógł zostać wysłany, ale skuteczność dostarczania wymaga poprawy.','We\'re sorry, the %mailer% mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Niestety, usługa pocztowa %mailer% nie jest dostępna w twoim planie. Kup PRO, aby uzyskać dostęp do tej i innych fantastycznych funkcji.','<strong>Bonus:</strong> WP Mail SMTP users get <span class="highlight">%s off</span> regular price,<br>applied at checkout.'=>'<strong>Bonus:</strong> użytkownicy wtyczki WP Mail SMTP otrzymują <span class="highlight">zniżkę %s</span> od ceny standardowej,<br>która zostanie automatycznie zastosowana na etapie płatności.','WP Mail SMTP &rsaquo; Setup Wizard'=>'WP Mail SMTP &rsaquo; Kreator konfiguracji','Whoops, something\'s not working.'=>'Ups, coś nie działa.','It looks like something is preventing JavaScript from loading on your website. WP Mail SMTP requires JavaScript in order to give you the best possible experience.'=>'Wygląda na to, że coś uniemożliwia wczytywanie skryptów JavaScript w twojej witrynie internetowej. Wtyczka WP Mail SMTP wymaga obsługi skryptów JavaScript w celu zapewnienia optymalnego komfortu użytkowania.','In order to fix this issue, please check each of the items below:'=>'Aby naprawić ten problem, sprawdź każdą z poniższych pozycji:','If you are using an ad blocker, please disable it or whitelist the current page.'=>'Jeśli korzystasz z narzędzia do blokowania reklam, wyłącz je lub umieść obecną stronę na białej liście.','If you aren\'t already using Chrome, Firefox, Safari, or Edge, then please try switching to one of these popular browsers.'=>'Jeśli nie korzystasz jeszcze z programu Chrome, Firefox, Safari lub Edge, spróbuj przejść na jedną z tych popularnych przeglądarek.','Confirm that your browser is updated to the latest version.'=>'Upewnij się, że używana przeglądarka jest zaktualizowana do najnowszej wersji.','If you\'ve checked each of these details and are still running into issues, then please get in touch with our support team. We’d be happy to help!'=>'Jeśli po sprawdzeniu każdego z tych szczegółów nadal występują problemy, skontaktuj się z naszym zespołem pomocy technicznej. Chętnie pomożemy!','Copy the error message above and paste it in a message to the WP Mail SMTP support team.'=>'Skopiuj powyższy komunikat o błędzie i wklej go do wiadomości przeznaczonej dla zespołu pomocy technicznej wtyczki WP Mail SMTP.','Contact Us'=>'Skontaktuj się z nami','You don\'t have permission to change options for this WP site!'=>'Nie masz uprawnień do zmieniania opcji tej witryny WordPressa!','Could not install the plugin. You don\'t have permission to install plugins.'=>'Nie można było zainstalować wtyczki. Nie masz uprawnień do instalowania wtyczek.','Could not install the plugin. Plugin slug is missing.'=>'Nie można było zainstalować wtyczki. Brak uproszczonej nazwy wtyczki.','Could not install the plugin. Don\'t have file permission.'=>'Nie można było zainstalować wtyczki. Nie masz uprawnień do pliku.','Could not install the plugin. WP Plugin installer initialization failed.'=>'Nie można było zainstalować wtyczki. Nie udało się zainicjować instalatora wtyczki do WordPressa.','Could not install the plugin. WP Plugin installer could not retrieve plugin information.'=>'Nie można było zainstalować wtyczki. Instalatorowi wtyczki do WordPressa nie udało się pobrać informacji o wtyczce.','Google Analytics by MonsterInsights'=>'Google Analytics od MonsterInsights','All in One SEO'=>'All in One SEO','Giveaways by RafflePress'=>'Giveaways od RafflePress','Smash Balloon Social Photo Feed'=>'Smash Balloon Social Photo Feed','SeedProd Landing Page Builder'=>'Kreator stron docelowych SeedProd','WP Call Button'=>'WP Call Button','You are already using the WP Mail SMTP PRO version. Please refresh this page and verify your license key.'=>'Korzystasz już z wersji WP Mail SMTP PRO. Odśwież tę stronę i zweryfikuj klucz licencyjny.','You don\'t have the permission to perform this action.'=>'Nie masz uprawnienia do wykonania tego działania.','Please enter a valid license key!'=>'Wpisz prawidłowy klucz licencyjny!','Upgrade functionality not available!'=>'Funkcja ulepszenia jest niedostępna!','OK'=>'OK','Almost Done'=>'Prawie gotowe','Oops!'=>'Ups!','Unfortunately there was a server connection error.'=>'Niestety wystąpił błąd połączenia z serwerem.','You are not allowed to install plugins.'=>'Nie masz uprawnień do instalowania wtyczek.','Please enter your license key to connect.'=>'Wpisz klucz licencyjny, aby się połączyć.','Only the Lite version can be upgraded.'=>'Można ulepszyć tylko wersję Lite.','WP Mail SMTP Pro was already installed, but was not active. We activated it for you.'=>'Wtyczka WP Mail SMTP Pro była już zainstalowana, ale nie włączona. Włączyliśmy ją dla ciebie.','There was an error while generating an upgrade URL. Please try again.'=>'Podczas generowania adresu URL ulepszenia wystąpił błąd. Spróbuj ponownie.','There was an error while installing an upgrade. Please download the plugin from wpmailsmtp.com and install it manually.'=>'Podczas instalowania ulepszenia wystąpił błąd. Pobierz wtyczkę ze strony wpmailsmtp.com i zainstaluj ją ręcznie.','There was an error while installing an upgrade. Please check file system permissions and try again. Also, you can download the plugin from wpmailsmtp.com and install it manually.'=>'Podczas instalowania ulepszenia wystąpił błąd. Sprawdź uprawnienia do systemu plików i spróbuj ponownie. Możesz też pobrać wtyczkę ze strony wpmailsmtp.com i zainstalować ją ręcznie.','There was an error while installing an upgrade. Please try again.'=>'Podczas instalowania ulepszenia wystąpił błąd. Spróbuj ponownie.','Pro version installed but needs to be activated on the Plugins page.'=>'Wersja Pro została zainstalowana, ale wymaga włączenia na stronie Wtyczki.','Please input the sending domain/subdomain you configured in your Brevo (formerly Sendinblue) dashboard. More information can be found in our <a href="%s" target="_blank" rel="noopener noreferrer">Brevo documentation</a>.'=>'Wpisz domenę/poddomenę wysyłającą, która została skonfigurowana w kokpicie Brevo (dawniej Sendinblue). Więcej informacji można znaleźć w <a href="%s" target="_blank" rel="noopener noreferrer">dokumentacji usługi Brevo</a>.','Sending Domain'=>'Domena wysyłająca','Please input the sending domain/subdomain you configured in your SendGrid dashboard. More information can be found in our <a href="%s" target="_blank" rel="noopener noreferrer">SendGrid documentation</a>.'=>'Wpisz domenę/poddomenę wysyłającą, która została skonfigurowana w kokpicie SendGrid. Więcej informacji można znaleźć w <a href="%s" target="_blank" rel="noopener noreferrer">dokumentacji usługi SendGrid</a>.','Multisite'=>'Sieć witryn','Pro+ badge icon'=>'Ikonka odznaki Pro+','Simply enable network-wide settings and every site on your network will inherit the same SMTP settings. Save time and only configure your SMTP provider once.'=>'Wystarczy, że włączysz ustawienia dla całej sieci, a każda witryna znajdująca się w twojej sieci odziedziczy te same ustawienia SMTP. Skonfiguruj dostawcę SMTP tylko raz i zaoszczędź czas.','Settings control'=>'Kontrola ustawień','Make the plugin settings global network-wide'=>'Spraw, aby ustawienia wtyczki obowiązywały globalnie w całej sieci','If disabled, each subsite of this multisite will have its own WP Mail SMTP settings page that has to be configured separately.'=>'Jeśli ta opcja jest wyłączona, każda podwitryna wchodząca w skład tej sieci wielu witryn będzie mieć własną stronę ustawień wtyczki WP Mail SMTP, którą trzeba będzie skonfigurować osobno.','If enabled, these global settings will manage email sending for all subsites of this multisite.'=>'Jeśli ta opcja jest włączona, te ustawienia globalne będą określać sposób wysyłania e-maili ze wszystkich podwitryn należących do tej sieci wielu witryn.','Please make sure your Google Client ID and Secret in the plugin settings are valid. Save the settings and try the Authorization again.'=>'Upewnij się, że w ustawieniach wtyczki zdefiniowano prawidłowy identyfikator i klucz prywatny klienta Google. Zapisz ustawienia i jeszcze raz spróbuj przeprowadzić autoryzację.','The response object is invalid (missing getId method).'=>'Obiekt odpowiedzi jest nieprawidłowy (brak metody getId).','The email message ID is missing.'=>'Brak identyfikatora wiadomości e-mail.','The password is encrypted in the database, but for improved security we recommend using your site\'s WordPress configuration file to set your password.'=>'Hasło w bazie danych jest zaszyfrowane, ale dla większego bezpieczeństwa warto ustawić hasło przy użyciu pliku konfiguracji WordPressa witryny.','Loading'=>'Wczytywanie','Zoho Mail'=>'Zoho Mail','We\'re sorry, the Zoho Mail mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Niestety, usługa pocztowa Zoho Mail nie jest dostępna w twoim planie. Kup PRO, aby uzyskać dostęp do tej i innych fantastycznych funkcji.','Lite install date'=>'Data instalacji wersji Lite','None selected'=>'Nic nie wybrano','M j, Y @ g:ia'=>'Y-m-d H:i','By allowing us to track usage data we can better help you because we know with which WordPress configurations, themes and plugins we should test.'=>'Jeśli zezwolisz na śledzenie danych o użyciu, będzie nam łatwiej ci pomagać, ponieważ będziemy wiedzieć, jakie konfiguracje, motywy i wtyczki do WordPressa powinniśmy testować.','Dismiss this message.'=>'Odrzuć ten komunikat.','Allow Usage Tracking'=>'Zezwól na śledzenie użycia','Dismiss this message'=>'Odrzuć ten komunikat','Previous message'=>'Poprzednia wiadomość','Next message'=>'Następna wiadomość','Plugin icon'=>'Ikonka wtyczki','Error'=>'Błąd','If you want to use a different From Email address you can set up a Google email alias. <a href="%s" target="_blank" rel="noopener noreferrer">Follow these instructions</a> and then select the From Email at the top of this page.'=>'Jeśli chcesz użyć innego adresu e-mail nadawcy, możesz skonfigurować alias adresu e-mail Google. <a href="%s" target="_blank" rel="noopener noreferrer">Postępuj zgodnie z tymi instrukcjami</a> , a następnie wybierz Adres e-mail nadawcy u góry strony.','General error'=>'Błąd ogólny','Do WP Mail SMTP DB tables exist?'=>'Czy istnieją tabele bazy danych WP Mail SMTP?','DB tables'=>'Tabele bazy danych','No DB tables found.'=>'Nie znaleziono tabel bazy danych.','WP Mail SMTP DB tables are created'=>'Tabele bazy danych WP Mail SMTP zostały utworzone','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it looks like they exist in your database.'=>'Wtyczka WP Mail SMTP używa własnych tabel bazy danych w przypadku niektórych swoich funkcji. Aby działało to poprawnie, powinny zostać utworzone tabele własne — i wygląda na to, że już istnieją w bazie danych.','WP Mail SMTP DB tables check has failed'=>'Sprawdzanie tabel bazy danych wtyczki WP Mail SMTP się nie powiodło','Missing table: %s'=>'Brakująca tabela: %s' . "\0" . 'Brakujące tabele: %s' . "\0" . 'Brakujące tabele: %s','Heads up!'=>'Uwaga!','<p>The Default (PHP) mailer is currently selected, but is not recommended because in most cases it does not resolve email delivery issues.</p><p>Please consider selecting and configuring one of the other mailers.</p>'=>'<p>Obecnie jest wybrana domyślna usługa pocztowa (PHP), ale nie jest ona zalecana, ponieważ w większości przypadków nie rozwiązuje problemów z dostarczaniem e-maili.</p><p>Rozważ wybór i skonfigurowanie jednej z pozostałych usług pocztowych.</p>','Cancel'=>'Anuluj','Warning icon'=>'Ikonka ostrzeżenia','I already did'=>'Już zrobione','There was an error while upgrading the database. Please contact %1$s support with this information: %2$s.'=>'Podczas ulepszania bazy danych wystąpił błąd. Skontaktuj się z zespołem pomocy technicznej %1$s, podając następujące informacje: %2$s.','No, maybe later'=>'Może później','Yes'=>'Tak','Please read this <a href="%s" target="_blank" rel="noopener noreferrer">support article</a> if you want to enable this option using constants.'=>'Jeśli chcesz włączyć tę opcję za pomocą stałych, zapoznaj się z <a href="%s" target="_blank" rel="noopener noreferrer">tym artykułem pomocy technicznej</a>.','Misconfigured server certificate.'=>'Niepoprawnie skonfigurowany certyfikat serwera.','Verify that the host\'s SSL certificate is valid.'=>'Sprawdź, czy certyfikat SSL hosta jest prawidłowy.','Go to WP Mail SMTP plugin settings page. Click the “Remove OAuth Connection” button.'=>'Przejdź do strony ustawień wtyczki WP Mail SMTP. Kliknij przycisk „Usuń połączenie OAuth”.','Then click the “Allow plugin to send emails using your Google account” button and re-enable access.'=>'Następnie kliknij przycisk „Zezwól wtyczce na wysyłanie e-maili przy użyciu twojego konta Google” i ponownie włącz dostęp.','SMTP.com API Error.'=>'Błąd SMTP.com API.','Please make sure you entered an accurate Sender Name in WP Mail SMTP plugin settings.'=>'Koniecznie wpisz odpowiednie imię i nazwisko (lub nazwę) nadawcy w ustawieniach wtyczki WP Mail SMTP.','GuzzleHttp requirements.'=>'Wymagania GuzzleHttp.','Edit your php.ini file on your hosting server.'=>'Edytuj plik php.ini na swoim serwerze hostingowym.','Are you enjoying WP Mail SMTP?'=>'Czy podoba ci się wtyczka WP Mail SMTP?','We\'re sorry to hear you aren\'t enjoying WP Mail SMTP. We would love a chance to improve. Could you take a minute and let us know what we can do better?'=>'Przykro nam słyszeć, że nie podoba ci się wtyczka WP Mail SMTP. Chcielibyśmy ją udoskonalić. Czy poświęcisz trochę czasu, aby nam powiedzieć, co można w niej ulepszyć?','No thanks'=>'Nie, dziękuję','Please re-grant Google app permissions!'=>'Ponownie przyznaj uprawnienia aplikacji Google!','%s requires an SSL certificate, and so is not currently compatible with your site. Please contact your host to request a SSL certificate, or check out <a href="https://www.wpbeginner.com/wp-tutorials/how-to-add-ssl-and-https-in-wordpress/" target="_blank">WPBeginner\'s tutorial on how to set up SSL</a>.'=>'%s wymaga certyfikatu SSL, więc nie jest obecnie zgodny z twoją witryną. Skontaktuj się z dostawcą hostingu, aby poprosić o certyfikat SSL, lub zapoznaj się z <a href="https://www.wpbeginner.com/wp-tutorials/how-to-add-ssl-and-https-in-wordpress/" target="_blank">poradnikiem WPBeginner dotyczącym konfigurowania protokołu SSL</a>.','If you\'d prefer not to set up SSL, or need an SMTP solution in the meantime, please select a different mailer option.'=>'Jeśli wolisz nie konfigurować protokołu SSL lub w międzyczasie potrzebujesz rozwiązania SMTP, wybierz inną usługę pocztową.','Learn More'=>'Dowiedz się więcej','Get Started with Pepipost'=>'Rozpocznij korzystanie z usługi Pepipost','Sender Name'=>'Imię i nazwisko nadawcy','Get Started with SMTP.com'=>'Rozpocznij korzystanie z usługi SMTP.com','Get API Key'=>'Uzyskaj klucz API','SMTP.com'=>'SMTP.com','Follow this link to get an API Key from SMTP.com: %s.'=>'Kliknij ten odnośnik, aby uzyskać klucz API usługi SMTP.com: %s.','Follow this link to get a Sender Name from SMTP.com: %s.'=>'Kliknij ten odnośnik, aby uzyskać imię i nazwisko nadawcy z usługi SMTP.com: %s.','Get Sender Name'=>'Uzyskaj imię i nazwisko nadawcy','Go to WP Mail SMTP Settings page'=>'Przejdź do strony Ustawienia wtyczki WP Mail SMTP','Don\'t see what you\'re looking for?'=>'Nie widzisz tego, czego szukasz?','Api Key:'=>'Klucz API:','Channel:'=>'Kanał:','Changes that you made to the settings are not saved!'=>'Zmiany wprowadzone w ustawieniach nie zostały zapisane!','RafflePress Pro'=>'RafflePress Pro','Is WP Mail SMTP mailer setup complete?'=>'Czy konfiguracja usługi pocztowej WP Mail SMTP została ukończona?','License key type'=>'Typ klucza licencyjnego','No debug notices found.'=>'Nie znaleziono powiadomień dotyczących debugowania.','Current mailer'=>'Obecna usługa pocztowa','WP Mail SMTP mailer setup is complete'=>'Konfiguracja usługi pocztowej WP Mail SMTP została ukończona','The WP Mail SMTP plugin mailer setup is complete. You can send a test email, to make sure it\'s working properly.'=>'Konfiguracja usługi pocztowej wtyczki WP Mail SMTP została ukończona. Możesz wysłać e-maila testowego, aby sprawdzić, czy działa ona poprawnie.','Test email sending'=>'Testuj wysyłanie e-maili','You currently have the default mailer selected, which means that you haven’t set up SMTP yet.'=>'Obecnie masz wybraną domyślną usługę pocztową, co oznacza, że jeszcze nie masz skonfigurowanego SMTP.','WP Mail SMTP mailer setup is incomplete'=>'Konfiguracja usługi pocztowej wtyczki WP Mail SMTP nie została ukończona','The WP Mail SMTP plugin mailer setup is incomplete. Please click on the link below to access plugin settings and configure the mailer.'=>'Konfiguracja usługi pocztowej wtyczki WP Mail SMTP nie została ukończona. Kliknij poniższy odnośnik, aby uzyskać dostęp do ustawień wtyczki i skonfigurować usługę pocztową.','Configure mailer'=>'Skonfiguruj usługę pocztową','Debug'=>'Debugowanie','WP Mail SMTP is brought to you by the same team that\'s behind the most user friendly WordPress forms, <a href="%1$s" target="_blank" rel="noopener noreferrer">WPForms</a>, the largest WordPress resource site, <a href="%2$s" target="_blank" rel="noopener noreferrer">WPBeginner</a>, the most popular lead-generation software, <a href="%3$s" target="_blank" rel="noopener noreferrer">OptinMonster</a>, the best WordPress analytics plugin, <a href="%4$s" target="_blank" rel="noopener noreferrer">MonsterInsights</a>, and <a href="%5$s" target="_blank" rel="noopener noreferrer">more</a>.'=>'Wtyczka WP Mail SMTP została opracowana przez ten sam zespół, który stworzył najłatwiejsze w obsłudze formularze do WordPressa – <a href="%1$s" target="_blank" rel="noopener noreferrer">WPForms</a>, największy serwis z zasobami dotyczącymi WordPressa – <a href="%2$s" target="_blank" rel="noopener noreferrer">WPBeginner</a>, najpopularniejsze oprogramowanie do generowania potencjalnych klientów – <a href="%3$s" target="_blank" rel="noopener noreferrer">OptinMonster</a>, najlepszą wtyczkę analityczną do WordPressa – <a href="%4$s" target="_blank" rel="noopener noreferrer">MonsterInsights</a> i <a href="%5$s" target="_blank" rel="noopener noreferrer">inne narzędzia</a>.','RafflePress'=>'RafflePress','Suggest a Mailer'=>'Zaproponuj usługę pocztową','Pepipost SMTP'=>'Pepipost SMTP','Read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Pepipost documentation</a> to learn how to configure Pepipost and improve your email deliverability.'=>'Aby się dowiedzieć, jak skonfigurować usługę Pepipost i zwiększyć skuteczność dostarczania e-maili, zapoznaj się z <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentacją usługi Pepipost</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Pepipost</a> is a transactional email service. Every month Pepipost delivers over 8 billion emails from 20,000+ customers. Their mission is to reliably send emails in the most efficient way and at the most disruptive pricing ever. Pepipost provides users 30,000 free emails the first 30 days.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Pepipost</a> to transakcyjna usługa e-mail. Każdego miesiąca Pepipost dostarcza ponad 8 miliardów e-maili od ponad 20 000 klientów. Misją tej usługi jest niezawodne wysyłanie e-maili w maksymalnie efektywny sposób i po najbardziej rewolucyjnych cenach w historii. Pepipost zapewnia użytkownikom 30 000 darmowych e-maili przez pierwsze 30 dni.','Get the API Key'=>'Uzyskaj klucz API','Download'=>'Pobierz','<strong>EMAILING DISABLED:</strong> The %s is currently blocking all emails from being sent.'=>'<strong>WYŁĄCZONO WYSYŁANIE E-MAILI:</strong> wtyczka %s obecnie blokuje wysyłanie jakichkolwiek e-maili.','To send emails, change the value of the %1$s constant to %2$s.'=>'Aby wysyłać wiadomości e-mail, zmień wartość stałej %1$s na %2$s.','To send emails, go to plugin <a href="%s">Misc settings</a> and disable the "Do Not Send" option.'=>'Aby wysyłać e-maile, przejdź do <a href="%s">sekcji ustawień Różne</a> we wtyczce i wyłącz opcję „Nie wysyłaj”.','Amazon SES'=>'Amazon SES','We\'re sorry, the Amazon SES mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Niestety, usługa pocztowa Amazon SES nie jest dostępna w twoim planie. Kup PRO, aby uzyskać dostęp do tej i innych fantastycznych funkcji.','We\'re sorry, the Microsoft Outlook mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Niestety, usługa pocztowa Microsoft Outlook nie jest dostępna w twoim planie. Kup PRO, aby uzyskać dostęp do tej i innych fantastycznych funkcji.','Upgrade to Pro'=>'Kup Pro','%name% is a PRO Feature'=>'%name% jest funkcją PRO','<strong>Bonus:</strong> WP Mail SMTP users get <span>%s off</span> regular price,<br>applied at checkout.'=>'<strong>Bonus:</strong> użytkownicy wtyczki WP Mail SMTP otrzymują <span>zniżkę %s</span> od ceny standardowej,<br>która jest automatycznie stosowana na etapie płatności.','Already purchased?'=>'Już kupiony?','Educational notice for this mailer was successfully dismissed.'=>'Powiadomienie z dodatkowymi informacjami na temat tej usługi pocztowej zostało odrzucone.','Hide Email Delivery Errors'=>'Ukryj błędy dostarczania e-maili','Email Delivery Errors were disabled using a %s filter.'=>'Błędy dostarczania e-maili zostały wyłączone przy użyciu filtru %s.','<strong>This is not recommended</strong> and should only be done for staging or development sites.'=>'<strong>Nie jest to zalecane</strong> i powinno mieć miejsce wyłącznie w witrynach tymczasowych lub znajdujących się w fazie rozwoju.','Follow this link to get an API Key: %s.'=>'Kliknij ten odnośnik, aby uzyskać klucz API: %s.','Get v3 API Key'=>'Uzyskaj klucz API v3','The Gmail mailer works well for sites that send low numbers of emails. However, Gmail\'s API has rate limitations and a number of additional restrictions that can lead to challenges during setup.<br><br>If you expect to send a high volume of emails, or if you find that your web host is not compatible with the Gmail API restrictions, then we recommend considering a different mailer option.'=>'Usługa pocztowa Gmail dobrze się sprawdza w przypadku witryn, z których jest wysyłanych niewiele e-maili. Interfejs Gmail API ma jednak ograniczenia wskaźników i szereg innych ograniczeń, które mogą powodować problemy podczas konfiguracji.<br><br>Jeśli przewidujesz, że będziesz wysyłać dużo e-maili, lub używany hosting nie jest zgodny z ograniczeniami interfejsu Gmail API, rozważ korzystanie z innej usługi pocztowej.','https://wpmailsmtp.com/'=>'https://wpmailsmtp.com/','Meanwhile you can switch to some other mailers.'=>'Tymczasem możesz korzystać z innych usług pocztowych.','Activate'=>'Włącz','You have successfully linked the current site with your Google API project. Now you can start sending emails through Gmail.'=>'Udało się połączyć obecną witrynę z projektem Google API. Teraz możesz rozpocząć wysyłanie e-maili za pośrednictwem usługi Gmail.','<strong>WP Mail SMTP plugin is disabled</strong> on your site until you fix the issue. <a href="%s" target="_blank" rel="noopener noreferrer">Read more for additional information.</a>'=>'<strong>Wtyczka WP Mail SMTP w twojej witrynie została wyłączona</strong> do czasu rozwiązania tego problemu. <a href="%s" target="_blank" rel="noopener noreferrer">Przeczytaj więcej, aby uzyskać dodatkowe informacje.</a>','Your site is running an <strong>insecure version</strong> of PHP that is no longer supported. Please contact your web hosting provider to update your PHP version or switch to a <a href="%1$s" target="_blank" rel="noopener noreferrer">recommended WordPress hosting company</a>.'=>'Twoja witryna korzysta z <strong>niezabezpieczonej wersji</strong> języka PHP, która nie jest już obsługiwana. Skontaktuj się z dostawcą hostingu, aby zaktualizował wersję języka PHP, lub zmień <a href="%1$s" target="_blank" rel="noopener noreferrer">firmę hostingową na polecaną firmę zajmującą się hostingiem WordPressa</a>.','WP Mail SMTP Pro related message was successfully dismissed.'=>'Wiadomość związana z wtyczką WP Mail SMTP Pro została odrzucona.','Install and Activate'=>'Zainstaluj i włącz','Could not install a plugin. Please download from WordPress.org and install manually.'=>'Nie udało się zainstalować wtyczki. Pobierz ją ze strony WordPress.org i zainstaluj ręcznie.','Current provider will automatically force From Email to be the email address that you use to set up the OAuth connection below.'=>'Obecny dostawca jako adres e-mail nadawcy automatycznie wymusi adres e-mail użyty do skonfigurowania poniższego połączenia OAuth.','Current provider doesn\'t support setting and forcing From Name. Emails will be sent on behalf of the account name used to setup the OAuth connection below.'=>'Obecny dostawca nie obsługuje ustawiania i wymuszania imienia i nazwiska nadawcy. E-maile będą wysyłane w imieniu konta użytego do skonfigurowania poniższego połączenia OAuth.','License'=>'Licencja','Your license key provides access to updates and support.'=>'Klucz licencyjny zapewnia dostęp do aktualizacji i pomocy technicznej.','License Key'=>'Klucz licencyjny','Processing...'=>'Przetwarzanie…','Inactive'=>'Wyłączono','Yup, we know a thing or two about building awesome products that customers love.'=>'Tak, tak, wiemy co nieco o tworzeniu fantastycznych produktów, które klienci wprost uwielbiają.','The WPForms Team photo'=>'Zdjęcie zespołu WPForms','The WPForms Team'=>'Zespół WPForms','Status: %s'=>'Status: %s','OptinMonster'=>'OptinMonster','WPForms Pro'=>'WPForms Pro','MonsterInsights'=>'MonsterInsights','MonsterInsights Pro'=>'MonsterInsights Pro','Could not activate the plugin. Please activate it from the Plugins page.'=>'Nie udało się włączyć wtyczki. Włącz ją z poziomu strony Wtyczki.','Plugin activated.'=>'Wtyczka została włączona.','Could not install the plugin.'=>'Nie udało się zainstalować wtyczki.','Plugin installed & activated.'=>'Zainstalowano i włączono wtyczkę.','Plugin installed.'=>'Zainstalowano wtyczkę.','Email Controls'=>'Kontrola nad e-mailami','Enter email address where test email will be sent.'=>'Wpisz adres e-mail, na który zostanie wysłany e-mail testowy.','Get the most out of WP Mail SMTP by upgrading to Pro and unlocking all of the powerful features.'=>'Wykorzystaj w pełni możliwości wtyczki WP Mail SMTP — kup Pro i uzyskaj dostęp do wszystkich zaawansowanych funkcji.','Feature'=>'Funkcja','Pro'=>'Pro','Contact Forms by WPForms'=>'Formularze kontaktowe WPForms','Our goal is to make reliable email deliverability easy for WordPress.'=>'Naszym celem jest maksymalizacja skuteczności dostarczania e-maili z witryn w WordPressie.','Email deliverability has been a well-documented problem for all WordPress websites. However as WPForms grew, we became more aware of this painful issue that affects our users and the larger WordPress community. So we decided to solve this problem and make a solution that\'s beginner friendly.'=>'Mała skuteczność dostarczania e-maili to dobrze udokumentowany problem występujący we wszystkich witrynach internetowych w WordPressie. Jednak wraz z rozwojem wtyczki WPForms staliśmy się bardziej świadomi tej bolesnej kwestii, która dotyka naszych użytkowników i szerszą społeczność entuzjastów WordPressa. Dlatego postanowiliśmy opracować rozwiązanie – skuteczne i przyjazne dla początkujących.','Email Log'=>'Dziennik e-maili','Upgrade to WP Mail SMTP Pro'=>'Kup WP Mail SMTP Pro','About Us'=>'O nas','Hello and welcome to WP Mail SMTP, the easiest and most popular WordPress SMTP plugin. We build software that helps your site reliably deliver emails every time.'=>'Witamy w WP Mail SMTP – najłatwiejszej w obsłudze i najpopularniejszej wtyczce SMTP do WordPressa. Tworzymy oprogramowanie, które pomaga witrynom w skutecznym dostarczaniu wszystkich e-maili.','Please copy this URL into the "Authorized redirect URIs" field of your Google web application.'=>'Skopiuj adres URL do pola „Autoryzowane identyfikatory URI przekierowania” w aplikacji internetowej Google.','Connected as %s'=>'Połączono jako %s','You need to save settings with Client ID and Client Secret before you can proceed.'=>'Zanim przejdziesz dalej, musisz zapisać ustawienia identyfikatora klienta i klucza prywatnego klienta.','%1$s \\a\\t %2$s'=>'%1$s \\\\t %2$s','The value of this field was set using a constant %1$s most likely inside %2$s of your WordPress installation.'=>'Wartość tego pola została ustawiona najprawdopodobniej za pomocą stałej %1$s w pliku %2$s instalacji WordPressa.','To change the password you need to change the value of the constant there: %s'=>'Aby zmienić hasło, musisz tam zmienić wartość stałej: %s','If you want to disable the use of constants, find in %1$s file the constant %2$s and turn if off:'=>'Jeśli chcesz wyłączyć używanie stałych, znajdź w pliku %1$s stałą %2$s i ją wyłącz:','All the defined constants will stop working and you will be able to change all the values on this page.'=>'Wszelkie zdefiniowane stałe przestaną działać i będzie można zmieniać wszystkie wartości na tej stronie.','Please deactivate the free version of the WP Mail SMTP plugin before activating WP Mail SMTP Pro.'=>'Zanim włączysz wtyczkę WP Mail SMTP Pro, wyłącz bezpłatną wersję wtyczki WP Mail SMTP.','Private API Key'=>'Prywatny klucz API','Domain Name'=>'Nazwa domeny','Region'=>'Region','Force From Name'=>'Wymuś imię i nazwisko nadawcy','Force From Email'=>'Wymuś adres e-mail nadawcy','The name that emails are sent from.'=>'Imię i nazwisko osoby wysyłającej e-maile.','The email address that emails are sent from.'=>'Adres e-mail, z którego są wysyłane e-maile.','US'=>'USA','EU'=>'UE','API Key'=>'Klucz API','Client ID'=>'Identyfikator klienta','Client Secret'=>'Klucz prywatny klienta','Authorization'=>'Autoryzacja','Auto TLS'=>'Auto TLS','By default, TLS encryption is automatically used if the server supports it (recommended). In some cases, due to server misconfigurations, this can cause issues and may need to be disabled.'=>'Domyślnie szyfrowanie TLS jest używane automatycznie, jeśli serwer je obsługuje (ustawienie zalecane). W pewnych przypadkach z powodu błędnej konfiguracji serwera to ustawienie może powodować problemy i może wymagać wyłączenia.','Enable Authentication'=>'Włącz uwierzytelnianie','SMTP Username'=>'Nazwa użytkownika SMTP','SMTP Password'=>'Hasło SMTP','For most servers TLS is the recommended option. If your SMTP provider offers both SSL and TLS options, we recommend using TLS.'=>'W przypadku większości serwerów zalecana opcja to TLS. Jeśli dostawca SMTP oferuje zarówno szyfrowanie SSL, jak i TLS, zalecamy korzystanie z TLS.','None'=>'Brak','SSL'=>'SSL','TLS'=>'TLS','There was an error while processing the authentication request. Please try again.'=>'Podczas przetwarzania żądania uwierzytelnienia wystąpił błąd. Spróbuj ponownie.','You have successfully linked the current site with your Zoho Mail API project. Now you can start sending emails through Zoho Mail.'=>'Udało się połączyć obecną witrynę z projektem Zoho Mail API. Teraz możesz rozpocząć wysyłanie e-maili za pośrednictwem usługi Zoho Mail.','Install'=>'Zainstaluj','Activated'=>'Włączono','There was an error while processing the authentication request: %s. Please try again.'=>'Podczas przetwarzania żądania uwierzytelnienia wystąpił błąd: %s. Spróbuj ponownie.','There was an error while processing the authentication request. Please make sure that you have Client ID and Client Secret both valid and saved.'=>'Podczas przetwarzania żądania uwierzytelnienia wystąpił błąd. Upewnij się, że identyfikator klienta oraz klucz prywatny klienta są prawidłowe i zostały zapisane.','Thanks for using WP Mail SMTP! To complete the plugin setup and start sending emails, <strong>please select and configure your <a href="%s">Mailer</a></strong>.'=>'Dziękujemy za skorzystanie z wtyczki WP Mail SMTP! Aby dokończyć jej konfigurację i rozpocząć wysyłanie e-maili, <strong>wybierz i skonfiguruj <a href="%s">usługę pocztową</a></strong>.','General'=>'Ogólne','Are you sure you want to reset the current provider connection? You will need to immediately create a new one to be able to send emails.'=>'Czy na pewno chcesz zresetować obecne połączenie z dostawcą? Aby było możliwe wysyłanie e-maili, trzeba będzie natychmiast utworzyć nowe połączenie.','Save Settings'=>'Zapisz ustawienia','Active'=>'Włączono','Please rate <strong>WP Mail SMTP</strong> <a href="%1$s" target="_blank" rel="noopener noreferrer">&#9733;&#9733;&#9733;&#9733;&#9733;</a> on <a href="%2$s" target="_blank" rel="noopener noreferrer">WordPress.org</a> to help us spread the word. Thank you from the WP Mail SMTP team!'=>'Oceń wtyczkę <strong>WP Mail SMTP</strong> <a href="%1$s" target="_blank" rel="noopener noreferrer">&#9733;&#9733;&#9733;&#9733;&#9733;</a> na <a href="%2$s" target="_blank" rel="noopener noreferrer">WordPress.org</a>, aby przyczynić się do jej popularyzacji. Podziękowania od zespołu WP Mail SMTP!','If you\'re using an email provider (Yahoo, Outlook.com, etc) this should be your email address for that account.'=>'Jeśli korzystasz z dostawcy usług e-mail (Yahoo, Outlook.com itp.), powinien to być adres e-mail związany z tym kontem.','Please note that other plugins can change this, to prevent this use the setting below.'=>'Zwracamy uwagę, że inne wtyczki mogą to zmienić. Aby temu zapobiec, użyj poniższego ustawienia.','If checked, the From Email setting above will be used for all emails, ignoring values set by other plugins.'=>'W przypadku zaznaczenia tej opcji we wszystkich e-mailach będzie używany ustawiony wyżej adres e-mail nadawcy, a wartości ustawione przez inne wtyczki będą ignorowane.','If checked, the From Name setting above will be used for all emails, ignoring values set by other plugins.'=>'W przypadku zaznaczenia tej opcji we wszystkich e-mailach będą używane ustawione wyżej imię i nazwisko nadawcy, a wartości ustawione przez inne wtyczki będą ignorowane.','Return Path indicates where non-delivery receipts - or bounce messages - are to be sent.'=>'Ścieżka zwrotna wskazuje, gdzie mają być wysyłane potwierdzenia niedostarczenia, czyli wiadomości odrzucone.','If unchecked, bounce messages may be lost.'=>'Jeśli ta opcja nie jest zaznaczona, może dochodzić do utraty wiadomości odrzuconych.','Dismiss this notice'=>'Odrzuć to powiadomienie','Type'=>'Typ','Source'=>'Źródło','Not Installed'=>'Nie zainstalowano','Install Plugin'=>'Zainstaluj wtyczkę','WPForms'=>'WPForms','On'=>'Wł.','Off'=>'Wył.','Send To'=>'Wyślij do','Settings were successfully saved.'=>'Ustawienia zostały zapisane.','Status'=>'Status','Misc'=>'Różne','Do Not Send'=>'Nie wysyłaj','Some plugins, like BuddyPress and Events Manager, are using their own email delivery solutions. By default, this option does not block their emails, as those plugins do not use default <code>wp_mail()</code> function to send emails.'=>'Niektóre wtyczki, takie jak BuddyPress i Events Manager, korzystają z własnych rozwiązań do dostarczania e-maili. Domyślnie ta opcja nie blokuje e-maili wysyłanych przez te wtyczki, ponieważ nie wysyłają one e-maili przy użyciu domyślnej funkcji <code>wp_mail()</code>.','You will need to consult with their documentation to switch them to use default WordPress email delivery.'=>'Aby przełączyć je na domyślne dostarczanie e-maili z WordPressa, zapoznaj się z ich dokumentacją.','Test emails are allowed to be sent, regardless of this option.'=>'Wysyłanie e-maili testowych jest dozwolone niezależnie od tej opcji.','Hide Announcements'=>'Ukryj ogłoszenia','Uninstall WP Mail SMTP'=>'Odinstaluj wtyczkę WP Mail SMTP','Email Test'=>'Test e-maili','HTML'=>'HTML','Send this email in HTML or in plain text format.'=>'Wyślij ten e-mail w formacie HTML lub zwykłego tekstu.','You cannot send an email. Mailer is not properly configured. Please check your settings.'=>'Nie możesz wysłać e-maila. Usługa pocztowa nie jest poprawnie skonfigurowana. Sprawdź ustawienia.','Send Email'=>'Wyślij e-mail','Test failed. Please use a valid email address and try to resend the test email.'=>'Test się nie powiódł. Użyj prawidłowego adresu e-mail i jeszcze raz spróbuj wysłać e-mail testowy.','Test email to %s'=>'E-mail testowy na adres %s','SSL certificate issue.'=>'Problem z certyfikatami SSL.','Contact your web hosting provider and inform them your site has an issue with SSL certificates.'=>'Skontaktuj się z dostawcą hostingu i poinformuj go, że witryna ma problem z certyfikatami SSL.','Could not connect to host.'=>'Nie można było nawiązać połączenia z hostem.','Could not connect to your host.'=>'Nie można było nawiązać połączenia z twoim hostem.','Contact your web hosting provider and inform them you are having issues making outbound connections.'=>'Skontaktuj się z dostawcą hostingu i poinformuj go, że masz problemy z nawiązywaniem połączeń wychodzących.','Could not authenticate your SMTP account.'=>'Nie można było uwierzytelnić twojego konta SMTP.','Contact your SMTP host to confirm you are using the correct username and password.'=>'Skontaktuj się z dostawcą hostingu  SMTP, aby sprawdzić, czy używasz poprawnej nazwy użytkownika i hasła.','Verify with your SMTP host that your account has permissions to send emails using outside connections.'=>'Sprawdź u dostawcy hostingu SMTP, czy twoje konto ma uprawnienia do wysyłania e-maili przy użyciu połączeń zewnętrznych.','Error due to unsolicited and/or bulk e-mail.'=>'Błąd spowodowany niechcianą i/lub zbiorczą pocztą e-mail.','Unauthenticated senders are not allowed.'=>'Nieuwierzytelnieni nadawcy nie są dozwoleni.','Could not connect to the SMTP host.'=>'Nie można było nawiązać połączenia z dostawcą hostingu SMTP.','Typically this error is returned for one of the following reasons:'=>'Błąd ten jest zwykle zwracany z jednego z następujących powodów:','Your web server is blocking the connection.'=>'Serwer WWW blokuje połączenie.','Your SMTP host is rejecting the connection.'=>'Dostawca hostingu SMTP odrzuca połączenie.','Mailgun failed.'=>'Niepowodzenie usługi Mailgun.','Go to our how-to guide for setting up <a href="%s" target="_blank" rel="noopener noreferrer">Mailgun with WP Mail SMTP</a>.'=>'Aby się dowiedzieć, jak skonfigurować <a href="%s" target="_blank" rel="noopener noreferrer">usługę Mailgun do współpracy z wtyczką WP Mail SMTP</a>, zajrzyj do naszej instrukcji.','Complete the steps in section "2. Verify Your Domain".'=>'Wykonaj kroki opisane w sekcji „2. Sprawdź domenę”.','Google API Error.'=>'Błąd Google API.','An issue was detected.'=>'Wykryto problem.','Your host is rejecting the connection.'=>'Host odrzuca połączenie.','Heads up! WP Mail SMTP has detected %1$s is activated. Please deactivate %1$s to prevent conflicts.'=>'Uwaga! Wtyczka WP Mail SMTP wykryła, że jest włączona wtyczka %1$s. Wyłącz wtyczkę %1$s , aby zapobiec konfliktom.','Authorized redirect URI'=>'Autoryzowany identyfikator URI przekierowania','Copy URL to clipboard'=>'Skopiuj adres URL do schowka','Allow plugin to send emails using your Google account'=>'Zezwól wtyczce na wysyłanie e-maili przy użyciu twojego konta Google','Click the button above to confirm authorization.'=>'Kliknij powyższy przycisk, aby potwierdzić autoryzację.','Removing the OAuth connection will give you an ability to redo the OAuth connection or link to another Google account.'=>'Usunięcie połączenia OAuth umożliwi ci ponowne nawiązanie połączenia OAuth lub powiązanie z innym kontem Google.','Default (none)'=>'Domyślna (brak)','Mailgun'=>'Mailgun','Follow this link to get a Domain Name from Mailgun: %s.'=>'Kliknij ten odnośnik, aby uzyskać nazwę domeny z usługi Mailgun: %s.','Get a Domain Name'=>'Uzyskaj nazwę domeny','Define which endpoint you want to use for sending messages.'=>'Określ, którego punktu końcowego chcesz używać do wysyłania wiadomości.','If you are operating under EU laws, you may be required to use EU region.'=>'Jeśli podlegasz przepisom UE, może być wymagane użycie regionu UE.','<a href="%s" rel="" target="_blank">More information</a> on Mailgun.com.'=>'<a href="%s" rel="" target="_blank">Więcej informacji</a> na stronie Mailgun.com.','%1$s requires PHP %2$s to work and does not support your current PHP version %3$s. Please contact your host and request a PHP upgrade to the latest one.'=>'%1$s wymaga do działania języka PHP w wersji %2$s i nie obsługuje twojej obecnej wersji PHP: %3$s. Skontaktuj się z dostawcą hostingu i poproś o ulepszenie PHP do najnowszej wersji.','Pepipost'=>'Pepipost','SendGrid'=>'SendGrid','Follow this link to get an API Key from SendGrid: %s.'=>'Kliknij ten odnośnik, aby uzyskać klucz API usługi SendGrid: %s.','Create API Key'=>'Utwórz klucz API','To send emails you will need only a %s access level for this API key.'=>'Do wysyłania e-maili potrzebujesz tylko dostępu na poziomie %s dla tego klucza API.','Other SMTP'=>'Inne SMTP','Version'=>'Wersja','Settings'=>'Ustawienia','Save Changes'=>'Zapisz zmiany','WP Mail SMTP'=>'WP Mail SMTP','From Name'=>'Imię i nazwisko nadawcy','From Email'=>'Adres e-mail nadawcy','Send a Test Email'=>'Wyślij e-mail testowy','SMTP Host'=>'Host SMTP','Encryption'=>'Szyfrowanie','SMTP Port'=>'Port SMTP','Authentication'=>'Uwierzytelnianie','Mailer'=>'Usługa pocztowa','Return Path'=>'Ścieżka zwrotna','Email'=>'Adres e-mail']];